insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (30991, 'https://www.liquor.com/jerk-spiced-bloody-mary-recipe-8584488', 'liquor', 'Jerk-Spiced Bloody Mary', 'Toni Tipton-Martin', 'https://www.liquor.com/thmb/srUtUKmqK91vwse4JJAQNDFK5d4=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Jerk_Spiced_Bloody_Mary_Toni_Tipton-Martin_Credit_Clarkson_Potter_Brittany_Conerly_2500x2500-primary-06347b807efd4a14aab7fee7917a8ce7.jpg',  E'{"name": "Jerk-Spiced Bloody Mary", "@type": ["Recipe", "NewsArticle"], "image": {"url": "https://www.liquor.com/thmb/srUtUKmqK91vwse4JJAQNDFK5d4=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Jerk_Spiced_Bloody_Mary_Toni_Tipton-Martin_Credit_Clarkson_Potter_Brittany_Conerly_2500x2500-primary-06347b807efd4a14aab7fee7917a8ce7.jpg", "@type": "ImageObject", "width": 1500, "height": 1500}, "author": [{"url": "https://www.liquor.com/toni-tipton-martin-8576292", "name": "Toni Tipton-Martin", "@type": "Person"}], "@context": "http://schema.org", "headline": "Jerk-Spiced Bloody Mary", "prepTime": "PT180M", "nutrition": {"@type": "NutritionInformation", "calories": "118 kcal", "fatContent": "2 g", "fiberContent": "3 g", "sugarContent": "7 g", "sodiumContent": "621 mg", "proteinContent": "2 g", "cholesterolContent": "0 mg", "carbohydrateContent": "16 g", "saturatedFatContent": "0 g", "unsaturatedFatContent": "0 g"}, "publisher": {"url": "https://www.liquor.com", "logo": {"url": "https://www.liquor.com/thmb/0v9c3WJ13dxUhITL99kMYCMFNjM=/778x180/filters:no_upscale():max_bytes(150000):strip_icc()/Liquor_Schema_Logo-bcd957a10f6e48d5892e1b39c1580f44.png", "@type": "ImageObject", "width": 778, "height": 180}, "name": "Liquor.com", "@type": "Organization", "brand": "Liquor.com", "sameAs": ["https://www.facebook.com/liquor.com", "https://www.instagram.com/liquor", "https://www.pinterest.com/liquordotcom"], "publishingPrinciples": "https://www.liquor.com/about-us-4782181#toc-editorial-guidelines"}, "totalTime": "PT180M", "description": "This big-batch Bloody Mary recipe from award-winning author and food journalist Toni Tipton-Martin utilizes sweet-hot spices while swapping rum for vodka, creating a Southern- and Caribbean-style twist on the classic.", "recipeYield": ["10", "10 servings"], "dateModified": "2024-02-17T06:30:00.000-05:00", "datePublished": "2024-02-17T06:30:00.000-05:00", "aggregateRating": {"@type": "AggregateRating", "ratingCount": "55", "ratingValue": "3.9"}, "mainEntityOfPage": {"@id": "https://www.liquor.com/jerk-spiced-bloody-mary-recipe-8584488", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.liquor.com/cocktail-and-other-recipes-4779343", "name": "Cocktail & Other Recipes"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.liquor.com/cocktail-by-spirit-4779438", "name": "By Spirit"}, "@type": "ListItem", "position": 2}, {"item": {"@id": "https://www.liquor.com/rum-cocktails-4779434", "name": "Rum Cocktails"}, "@type": "ListItem", "position": 3}]}}, "recipeIngredient": ["1 quart tomato juice or Campbell\\u2019s V8 juice", "\\u00bd cup plus 1 tablespoon prepared jerk seasoning", "1 teaspoon celery salt", "3/4 ounce tablespoons Worcestershire sauce", "4 ounces fresh lime or lemon juice", "\\u00bd to 1\\u00bd teaspoons hot pepper sauce, or to taste", "8 ounces light or dark rum", "8\\u201310 lime or lemon wedges", "8\\u201310 celery stalks, with leaves"], "recipeInstructions": [{"text": "Combine the tomato juice, 1 tablespoon of the jerk seasoning, the celery salt, and Worcestershire sauce in a small microwave- safe pitcher. Microwave until bubbles just begin to form around the edge of the pitcher, 2 to 3 minutes.\\u00a0", "@type": "HowToStep"}, {"text": "Remove it from the microwave and stir to dissolve the seasoning. Add the lime juice, hot pepper sauce, and rum to the base.\\u00a0", "@type": "HowToStep"}, {"text": "Refrigerate several hours, until thoroughly chilled.", "@type": "HowToStep"}, {"text": "Place the remaining \\u00bd cup jerk seasoning on a saucer. Moisten the edges of tall glasses with a lime wedge. Press the edge of each glass into the seasoning to create a spiced rim.\\u00a0", "@type": "HowToStep"}, {"text": "Add ice to each glass, then pour in the mix. Garnish each glass with 1 lime wedge and a celery stalk.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:33:22.255419+00:00'::timestamptz, '2026-04-25 19:21:43.240950+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:17:03.924279+00:00'::timestamptz, NULL, NULL, NULL);
