: "1 1", "dateModified": "2023-05-23T18:04:19-04:00", "datePublished": "2023-04-21T12:38:17-04:00", "recipeCuisine": ["American"], "recipeCategory": ["Dinner", "Cocktail"], "aggregateRating": {"@type": "AggregateRating", "ratingCount": "1", "ratingValue": "5"}, "mainEntityOfPage": {"@id": "https://www.foodandwine.com/green-beast-margarita-7481563", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.foodandwine.com/drinks", "name": "Drinks"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.foodandwine.com/cocktails", "name": "Cocktails"}, "@type": "ListItem", "position": 2}, {"item": {"@id": "https://www.foodandwine.com/tequila-cocktails-7496742", "name": "Tequila Cocktails"}, "@type": "ListItem", "position": 3}, {"item": {"@id": "https://www.foodandwine.com/cocktails-spirits/margaritas", "name": "Margaritas"}, "@type": "ListItem", "position": 4}]}}, "recipeIngredient": ["\\u00b7 1 1/5 ounces Tequila blanco", "\\u00b7 1/2 ounce elderflower liqueur (such as St-Germain)", "\\u00b7 2 teaspoons agave nectar", "\\u00b7\\u00a0 \\u00a0 \\u00a0 1 \\u00bd tablespoons fresh lime juice (from 1 lime)", "\\u00b7 Half avocado", "Pineapple juice 1 oz", "\\u00b7 1 dash Tabasco", "Cracked pepper (for garnish)"], "recipeInstructions": [{"text": "Add tequila, elderflower liqueur, agave nectar, lime juice, avocado, pineapple juice, and tabasco into a blender with a few cubes of ice. Blend at medium speed until the avocado is fully blended, about 20 seconds.", "@type": "HowToStep"}, {"text": "Double-strain the mixture into a couple glass and garnish with cracked black pepper.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:52:05.282710+00:00'::timestamptz, '2026-04-25 19:25:15.233979+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:57.688406+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (39636, 'https://www.foodandwine.com/hebrew-hammer-cocktail-6833702', 'foodandwine', 'Hebrew Hammer', 'Naomi Levy', 'https://www.foodandwine.com/thmb/1fcPJNzSWtZy2ec2bRzXpBPT2vs=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Hebrew-Hammer-XL-RECIPE1222-fc37faec7f9e40ef96d10bff65c2022d.jpg',  E'{"name": "Hebrew Hammer", "@type": ["Recipe"], "image": {"url": "https://www.foodandwine.com/thmb/1fcPJNzSWtZy2ec2bRzXpBPT2vs=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Hebrew-Hammer-XL-RECIPE1222-fc37faec7f9e40ef96d10bff65c2022d.jpg", "@type": "ImageObject", "width": 1500, "height": 1500}, "author": [{"url": "https://www.foodandwine.com/naomi-levy-6833663", "name": "Naomi Levy", "@type": "Person"}], "review": [{"@type": "Review", "author": {"name": "MagentaPolenta9931", "@type": "Person"}, "reviewBody": "It\\u2019s pretty, it tastes good and I even went out and bought some framboise instead of use the blackberry liquor I had on hand but it didn\\u2019t make me feel the spirit of the sufganiya.", "reviewRating": {"@type": "Rating", "ratingValue": "3"}, "datePublished": "2023-12-08T13:01:40.500Z"}], "@context": "http://schema.org", "headline": "Hebrew Hammer", "nutrition": {"@type": "NutritionInformation", "calories": "963 kcal", "fatContent": "1 g", "fiberContent": "3 g", "sugarContent": "211 g", "sodiumContent": "18 mg", "proteinContent": "5 g", "cholesterolContent": "0 mg", "carbohydrateContent": "217 g", "saturatedFatContent": "0 g", "unsaturatedFatContent": "0 g"}, "publisher": {"url": "https://www.foodandwine.com", "logo": {"url": "https://www.foodandwine.com/thmb/uV0O06O8WNrLepjgxkntdVuRpeE=/112x112/filters:no_upscale():max_bytes(150000):strip_icc()/brand_logo_schema-f3b2e548eb6f4243ad527798593483e0.png", "@type": "ImageObject", "width": 112, "height": 112}, "name": "Food & Wine", "@type": "Organization", "brand": "Food & Wine", "sameAs": ["https://www.facebook.com/foodandwine", "https://www.instagram.com/foodandwine/?hl=en", "https://www.pinterest.com/foodandwine/", "https://flipboard.com/@foodandwine", "https://www.youtube.com/channel/UCKH_4hkRSyUSHDIFMzlGCRA", "https://en.wikipedia.org/wiki/Food_%26_Wine"], "publishingPrinciples": "https://www.foodandwine.com/about-us-6373913#toc-editorial-policies"}, "totalTime": "PT10M", "description": "Naomi Levy\\u2019s Hebrew Hammer is a fruity, bright pink Hanukkah cocktail that uses framboise to mimic the flavors of sufganiyot, Israeli doughnuts.", "recipeYield": "1", "dateModified": "2022-12-09T09:56:35-05:00", "datePublished": "2022-12-02T10:30:44-05:00", "recipeCuisine": ["American"], "recipeCategory": ["Cocktail"], "aggregateRating": {"@type": "AggregateRating", "ratingCount": "1", "ratingValue": "3"}, "mainEntityOfPage": {"@id": "https://www.foodandwine.com/hebrew-hammer-cocktail-6833702", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.foodandwine.com/drinks", "name": "Drinks"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.foodandwine.com/cocktails", "name": "Cocktails"}, "@type": "ListItem", "position": 2}, {"item": {"@id": "https://www.foodandwine.com/vodka-cocktails-7496738", "name": "Vodka Cocktails"}, "@type": "ListItem", "position": 3}]}}, "recipeIngredient": ["1 cup hot water (about 120\\u00b0F)", "1 tablespoon active dry yeast (from 2 [3/4-ounce] envelopes)", "1 cup granulated sugar", "Powdered sugar, for dusting", "1 1/2 ounces (3 tablespoons) vodka", "1 1/2 tablespoons fresh lemon juice (from 1 lemon)", "1/4 ounce (1/2 tablespoon) cr\\u00e8me de framboise (such as Giffard Cr\\u00e8me de Framboise)"], "recipeInstructions": [{"name": "Make the cocktail:", "text": "Combine 1 cup hot water and yeast in a small bowl; whisk until yeast is fully dissolved, about 20 seconds. Add granulated sugar; whisk until sugar is fully dissolved, about 1 minute. Let cool 5 minutes.", "@type": "HowToStep"}, {"text": "Dust outside of a coupe glass with powdered sugar. Set aside.", "@type": "HowToStep"}, {"text": "Combine vodka, lemon juice, 1 1/2 tablespoons \\u201cleavened\\u201d simple syrup, and framboise in a cocktail shaker filled with ice. Place lid on shaker; shake until mixture is cold, about 15 seconds. Strain into prepared coupe glass.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:52:10.418713+00:00'::timestamptz, '2026-04-25 19:25:17.534909+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:59.279447+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (39642, 'https://www.foodandwine.com/aperol-schvitz-cocktail-6833681', 'foodandwine', 'Aperol Schvitz', 'Naomi Levy', 'https://www.foodandwine.com/thmb/blPf7u2ui3wNW1HTuAfVFmK6EdA=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Aperol-Schvitz-FT-RECIPE1222-02e9c505fdef40e2baaa62cd8afb6274.jpg',  E'{"name": "Aperol Schvitz", "@type": ["Recipe"], "image": {"url": "https://www.foodandwine.com/thmb/blPf7u2ui3wNW1HTuAfVFmK6EdA=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Aperol-Schvitz-FT-RECIPE1222-02e9c505fdef40e2baaa62cd8afb6274.jpg", "@type": "ImageObject", "width": 1500, "height": 1000}, "author": [{"url": "https://www.foodandwine.com/naomi-levy-6833663", "name": "Naomi Levy", "@type": "Person"}], "@context": "http://schema.org", "headline": "Aperol Schvitz", "publisher": {"url": "https://www.foodandwine.com", "logo": {"url": "https://www.foodandwine.com/thmb/uV0O06O8WNrLepjgxkntdVuRpeE=/112x112/filters:no_upscale():max_bytes(150000):strip_icc()/brand_logo_schema-f3b2e548eb6f4243ad527798593483e0.png", "@type": "ImageObject", "width": 112, "height": 112}, "name": "Food & Wine", "@type": "Organization", "brand": "Food & Wine", "sameAs": ["https://www.facebook.com/foodandwine", "https://www.instagram.com/foodandwine/?hl=en", "https://www.pinterest.com/foodandwine/", "https://flipboard.com/@foodandwine", "https://www.youtube.com/channel/UCKH_4hkRSyUSHDIFMzlGCRA", "https://en.wikipedia.org/wiki/Food_%26_Wine"], "publishingPrinciples": "https://www.foodandwine.com/about-us-6373913#toc-editorial-policies"}, "totalTime": "PT5M", "description": "Celebrate Hanukkah with this fizzy, refreshing, and sweet-tart Aperol Schvitz cocktail recipe from Naomi Levy.", "recipeYield": "1", "dateModified": "2022-12-02T10:27:46-05:00", "datePublished": "2022-12-02T10:27:46-05:00", "recipeCuisine": ["American"], "recipeCategory": ["Entree"], "aggregateRating": {"@type": "AggregateRating", "ratingCount": "1", "ratingValue": "5"}, "mainEntityOfPage": {"@id": "https://www.foodandwine.com/aperol-schvitz-cocktail-6833681", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.foodandwine.com/drinks", "name": "Drinks"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.foodandwine.com/cocktails", "name": "Cocktails"}, "@type": "ListItem", "position": 2}]}}, "recipeIngredient": ["2 ounces (1/4 cup) seltzer water", "2 ounces (1/4 cup) dry sparkling wine (such as Prosecco)", "1 1/2 ounces (3 tablespoons) Manischewitz Concord Grape Kosher Wine\\u00a0", "3/4 ounce (1 1/2 tablespoons) Aperol", "1/2 tablespoon fresh lime juice (from 1 lime)", "Ice cubes", "Orange slice"], "recipeInstructions": [{"text": "Pour seltzer water, sparkling wine, kosher wine, Aperol, and lime juice into a wineglass. Stir once, and top with ice cubes. Garnish with orange slice.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:52:10.198374+00:00'::timestamptz, '2026-04-25 19:25:17.747084+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:47.087087+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (39659, 'https://www.foodandwine.com/recipes/salmon-martini', 'foodandwine', 'Salmon Martini', 'David Kupchinsky', 'https://www.foodandwine.com/thmb/Ri6I1LUDZ2Xv62pW13Ef6YKFpRE=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Salmon-Martini-XL-RECIPE1022-2000-e1d60ce22bae4d14905ee1cc5685a91c.jpg',  E'{"name": "Salmon Martini", "@type": ["Recipe", "NewsArticle"], "image": {"url": "https://www.foodandwine.com/thmb/Ri6I1LUDZ2Xv62pW13Ef6YKFpRE=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Salmon-Martini-XL-RECIPE1022-2000-e1d60ce22bae4d14905ee1cc5685a91c.jpg", "@type": "ImageObject", "width": 1500, "height": 1500}, "author": [{"name": "David Kupchinsky", "@type": "Person"}], "review": [{"@type": "Review", "author": {"name": "Jeanette", "@type": "Person"}, "reviewBody": "This was really good, I was prepared for it to give me \\"the ick\\" but I loved it, even my mom and brother who were very skeptical loved it. I don''t have caper berries but added just a few drops of caper brine. I did my gin and lox in the souse vide at 140 degrees for an hour and a half rather than sitting on the counter.", "reviewRating": {"@type": "Rating", "ratingValue": "5"}}, {"@type": "Review", "author": {"name": "AllTheFood!", "@type": "Person"}, "reviewBody": "I''m not opposed to the flavor profile but because the recipe suggests discarding the salmon after infusing the gin I find this recipe to be incredibly wasteful and therefore unappealing.", "reviewRating": {"@type": "Rating", "ratingValue": "1"}, "datePublished": "2024-07-31T19:07:46.064Z"}], "@context": "http://schema.org", "headline": "Salmon Martini", "publisher": {"url": "https://www.foodandwine.com", "logo": {"url": "https://www.foodandwine.com/thmb/uV0O06O8WNrLepjgxkntdVuRpeE=/112x112/filters:no_upscale():max_bytes(150000):strip_icc()/brand_logo_schema-f3b2e548eb6f4243ad527798593483e0.png", "@type": "ImageObject", "width": 112, "height": 112}, "name": "Food & Wine", "@type": "Organization", "brand": "Food & Wine", "sameAs": ["https://www.facebook.com/foodandwine", "https://www.instagram.com/foodandwine/?hl=en", "https://www.pinterest.com/foodandwine/", "https://flipboard.com/@foodandwine", "https://www.youtube.com/channel/UCKH_4hkRSyUSHDIFMzlGCRA", "https://en.wikipedia.org/wiki/Food_%26_Wine"], "publishingPrinciples": "https://www.foodandwine.com/about-us-6373913#toc-editorial-policies"}, "totalTime": "PT30250M", "description": "At Bar Moruno in Los Angeles, bartenders infuse gin with cold smoked salmon for a martini that&#39;s perfect for brunch.", "recipeYield": "1", "dateModified": "2022-09-29T11:17:44-04:00", "datePublished": "2022-09-29T11:17:44-04:00", "recipeCuisine": ["American"], "recipeCategory": ["Drink", "Cocktail"], "aggregateRating": {"@type": "AggregateRating", "ratingCount": "2", "ratingValue": "3"}, "mainEntityOfPage": {"@id": "https://www.foodandwine.com/recipes/salmon-martini", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.foodandwine.com/drinks", "name": "Drinks"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.foodandwine.com/cocktails", "name": "Cocktails"}, "@type": "ListItem", "position": 2}, {"item": {"@id": "https://www.foodandwine.com/cocktails-spirits/martinis", "name": "Martinis"}, "@type": "ListItem", "position": 3}]}}, "recipeIngredient": ["2 cups (16 ounces) gin (such as Tanqueray no. 10)", "0.5 cup (4 ounces) cold smoked salmon", "3 tablespoons (1 1/2 ounces) Salmon-Infused Gin", "2 tablespoons (1 ounce) blanco vermouth (such as Tximista, Lacuesta or Dolin Blanc)", "1 tablespoon (1/2 ounce) gin (such as Tanqueray no. 10)", "Pickled caperberry, for garnish"], "recipeInstructions": [{"name": "Make the martini:", "text": "Combine gin and salmon in an airtight container and let stand at room temperature for 1 week. Transfer to the refrigerator and chill for 2 weeks. Pour mixture through cheesecloth or oil filter paper to remove excess fat and clarify; discard salmon. Infused-gin can be stored in the freezer for up to 1 month.", "@type": "HowToStep"}, {"text": "Combine Salmon-Infused gin, vermouth and gin in a mixing glass. Add ice and stir until well chilled. Strain mixture into a chilled Nick &amp; Nora glass. Garnish with a caperberry.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:52:12.312689+00:00'::timestamptz, '2026-04-25 19:25:18.371049+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:17:37.841949+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (39685, 'https://www.foodandwine.com/recipes/boozy-frozen-strawberry-lemonade', 'foodandwine', 'Boozy Frozen Strawberry Lemonade', 'Claudia Fleming', 'https://www.foodandwine.com/thmb/2caRfAtj6-V5Ntn1lS7YdMUPYms=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Frozen-Strawberry-Lemon-Cocktail-FT-RECIPE0622-ecf959e3266d46e6ad55e96f84adca2a.jpg',  E'{"name": "Boozy Frozen Strawberry Lemonade", "@type": ["Recipe", "NewsArticle"], "image": {"url": "https://www.foodandwine.com/thmb/2caRfAtj6-V5Ntn1lS7YdMUPYms=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Frozen-Strawberry-Lemon-Cocktail-FT-RECIPE0622-ecf959e3266d46e6ad55e96f84adca2a.jpg", "@type": "ImageObject", "width": 1500, "height": 1000}, "video": {"name": "How to Make Boozy Frozen Strawberry Lemonade", "@type": "VideoObject", "duration": "PT31S", "contentUrl": "https://content.jwplatform.com/videos/NcY3BPBS-b5wQURW0.mp4", "uploadDate": "2023-06-27T15:19:50-04:00", "description": "In this video, Claudia Fleming shows you how to make a boozy frozen lemonade just in time for the summer. Using lemon vodka, limoncello, and Prosecco, blend all of them together with basil leaves. Now, blend together strawberries with lemon sorbet before straining in the basil mixture and blending it one last time. Finally, let the drink sit in the freezer for four hours. It\\u2019s delicious, refreshing, and will cool you off in the summer heat!", "thumbnailUrl": "https://cdn.jwplayer.com/v2/media/NcY3BPBS/poster.jpg?width=1280"}, "author": [{"url": "https://www.foodandwine.com/author/claudia-fleming", "name": "Claudia Fleming", "@type": "Person"}], "@context": "http://schema.org", "headline": "Boozy Frozen Strawberry Lemonade", "nutrition": {"@type": "NutritionInformation", "calories": "399 kcal", "fatContent": "0 g", "fiberContent": "3 g", "sugarContent": "71 g", "sodiumContent": "23 mg", "proteinContent": "1 g", "cholesterolContent": "0 mg", "carbohydrateContent": "79 g", "saturatedFatContent": "0 g", "unsaturatedFatContent": "0 g"}, "publisher": {"url": "https://www.foodandwine.com", "logo": {"url": "https://www.foodandwine.com/thmb/uV0O06O8WNrLepjgxkntdVuRpeE=/112x112/filters:no_upscale():max_bytes(150000):strip_icc()/brand_logo_schema-f3b2e548eb6f4243ad527798593483e0.png", "@type": "ImageObject", "width": 112, "height": 112}, "name": "Food & Wine", "@type": "Organization", "brand": "Food & Wine", "sameAs": ["https://www.facebook.com/foodandwine", "https://www.instagram.com/foodandwine/?hl=en", "https://www.pinterest.com/foodandwine/", "https://flipboard.com/@foodandwine", "https://www.youtube.com/channel/UCKH_4hkRSyUSHDIFMzlGCRA", "https://en.wikipedia.org/wiki/Food_%26_Wine"], "publishingPrinciples": "https://www.foodandwine.com/about-us-6373913#toc-editorial-policies"}, "totalTime": "PT260M", "description": "Pastry chef Claudia Fleming&#39;s frozen strawberry lemonade gets a boozy kick from Prosecco, lemon-flavored vodka, and limoncello. Add it to your summer cocktail rotation.", "recipeYield": "4", "dateModified": "2022-06-13T22:25:44-04:00", "datePublished": "2022-06-13T22:25:44-04:00", "recipeCuisine": ["American"], "recipeCategory": ["Drink", "Beverage"], "mainEntityOfPage": {"@id": "https://www.foodandwine.com/recipes/boozy-frozen-strawberry-lemonade", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.foodandwine.com/drinks", "name": "Drinks"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.foodandwine.com/cocktails", "name": "Cocktails"}, "@type": "ListItem", "position": 2}, {"item": {"@id": "https://www.foodandwine.com/vodka-cocktails-7496738", "name": "Vodka Cocktails"}, "@type": "ListItem", "position": 3}]}}, "recipeIngredient": ["0.5 cup (4 ounces) Prosecco", "6 tablespoons (3 ounces) lemon-flavored vodka", "0.25 cup loosely packed fresh basil leaves, plus more for garnish2", "2 tablespoons (1 ounce) limoncello", "1 cup (1/2 pint) lemon sorbet", "6 large (about 3 ounces total) fresh strawberries, hulled and halved lengthwise"], "recipeInstructions": [{"text": "Using a cocktail muddler or handle of a wooden spoon, muddle together Prosecco, vodka, basil, and limoncello in a cocktail shaker until basil is starting to bruise and tear into pieces. Set aside.", "@type": "HowToStep"}, {"text": "Process sorbet and strawberries in a blender until smooth, about 30 seconds. Pour basil infusion from cocktail shaker through a fine mesh strainer into blender; discard solids. Pulse just until combined, 3 to 4 pulses. Transfer blended mixture to a medium-size freezer-safe bowl or resealable container. Cover and freeze until firm, at least 4 hours or up to overnight (12 hours).", "@type": "HowToStep"}, {"text": "Remove frozen mixture from freezer; let stand at room temperature until softened slightly, about 10 minutes. Scoop mixture into blender; process until smooth, about 30 seconds. Divide evenly among 4 Champagne flutes or wine glasses. Garnish with additional basil, and serve immediately.", "@type": "HowToStep", "image": [{"url": "https://www.foodandwine.com/thmb/2caRfAtj6-V5Ntn1lS7YdMUPYms=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Frozen-Strawberry-Lemon-Cocktail-FT-RECIPE0622-ecf959e3266d46e6ad55e96f84adca2a.jpg", "@type": "ImageObject"}]}]}'::jsonb, '2026-04-23 20:52:14.901127+00:00'::timestamptz, '2026-04-25 19:25:19.621729+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:48.728621+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (39694, 'https://www.foodandwine.com/recipes/contratto-spritz', 'foodandwine', 'Contratto Spritz', 'Ben Hatch', 'https://www.foodandwine.com/thmb/dxefPiSpJwAc9AUwraq1WEnps9Y=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/contratto-spritz-FT-RECIPE0422-9d88669e5c4b42eea0d8f3dab2e0a894.jpg', '{"name": "Contratto Spritz", "@type": ["Recipe", "NewsArticle"], "image": {"url": "https://www.foodandwine.com/thmb/dxefPiSpJwAc9AUwraq1WEnps9Y=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/contratto-spritz-FT-RECIPE0422-9d88669e5c4b42eea0d8f3dab2e0a894.jpg", "@type": "ImageObject", "width": 1500, "height": 1000}, "author": [{"name": "Ben Hatch", "@type": "Person"}], "@context": "http://schema.org", "headline": "Contratto Spritz", "nutrition": {"@type": "NutritionInformation", "calories": "284 kcal", "fatContent": "0 g", "fiberContent": "0 g", "sugarContent": "27 g", "sodiumContent": "9 mg", "proteinContent": "0 g", "cholesterolContent": "0 mg", "carbohydrateContent": "35 g", "saturatedFatContent": "0 g", "unsaturatedFatContent": "0 g"}, "publisher": {"url": "https://www.foodandwine.com", "logo": {"url": "https://www.foodandwine.com/thmb/uV0O06O8WNrLepjgxkntdVuRpeE=/112x112/filters:no_upscale():max_bytes(150000):strip_icc()/brand_logo_schema-f3b2e548eb6f4243ad527798593483e0.png", "@type": "ImageObject", "width": 112, "height": 112}, "name": "Food & Wine", "@type": "Organization", "brand": "Food & Wine", "sameAs": ["https://www.facebook.com/foodandwine", "https://www.instagram.com/foodandwine/?hl=en", "https://www.pinterest.com/foodandwine/", "https://flipboard.com/@foodandwine", "https://www.youtube.com/channel/UCKH_4hkRSyUSHDIFMzlGCRA", "https://en.wikipedia.org/wiki/Food_%26_Wine"], "publishingPrinciples": "https://www.foodandwine.com/about-us-6373913#toc-editorial-policies"}, "totalTime": "PT5M", "description": "This Contratto Spritz recipe from The Elysian Bar in New Orleans yields the ideal aperitif, boasting sweet tangerine, herbal sage, and mild licorice flavors. Garnish it with a dehydrated lemon slice for the finishing touch.", "recipeYield": "1", "dateModified": "2022-04-07T12:27:38-04:00", "datePublished": "2022-04-07T12:27:38-04:00", "recipeCuisine": ["American"], "recipeCategory": ["Drink", "Cocktail"], "mainEntityOfPage": {"@id": "https://www.foodandwine.com/recipes/contratto-spritz", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.foodandwine.com/drinks", "name": "Drinks"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.foodandwine.com/cocktails", "name": "Cocktails"}, "@type": "ListItem", "position": 2}, {"item": {"@id": "https://www.foodandwine.com/cocktails-spirits/wine-cocktails", "name": "Wine cocktails"}, "@type": "ListItem", "position": 3}]}}, "recipeIngredient": ["0.25 cup (2 oz.) Contratto Aperitif", "0.25 cup (2 oz.) dry sparkling wine such as Prosecco", "0.25 cup (2 oz.) club soda", "1 Dehydrated Lemon Slice (recipe follows)"], "recipeInstructions": [{"text": "Fill a large chilled wine glass with ice. Add Contratto, sparkling wine, and club soda; stir once. Garnish glass with dehydrated lemon slice and serve.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:52:14.719147+00:00'::timestamptz, '2026-04-25 19:25:19.994759+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:50.806838+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (39756, 'https://www.foodandwine.com/recipes/watermelon-sangria', 'foodandwine', 'Watermelon Sangria', 'Andrew Zimmerman', 'https://www.foodandwine.com/thmb/N3tzQNYOSpiVTMZ_HLJEbRX4du4=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/fw2007_c_xl_watermelonsangria-a8e255f0c5b54aa2af3e875fca362936.jpg', '{"name": "Watermelon Sangria", "@type": ["Recipe", "NewsArticle"], "image": {"url": "https://www.foodandwine.com/thmb/N3tzQNYOSpiVTMZ_HLJEbRX4du4=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/fw2007_c_xl_watermelonsangria-a8e255f0c5b54aa2af3e875fca362936.jpg", "@type": "ImageObject", "width": 796, "height": 796}, "author": [{"url": "https://www.foodandwine.com/author/andrew-zimmerman", "name": "Andrew Zimmerman", "@type": "Person"}], "@context": "http://schema.org", "headline": "Watermelon Sangria", "nutrition": {"@type": "NutritionInformation", "calories": "2301 kcal", "fatContent": "2 g", "fiberContent": "6 g", "sugarContent": "231 g", "sodiumContent": "125 mg", "proteinContent": "8 g", "cholesterolContent": "0 mg", "carbohydrateContent": "293 g", "saturatedFatContent": "0 g", "unsaturatedFatContent": "0 g"}, "publisher": {"url": "https://www.foodandwine.com", "logo": {"url": "https://www.foodandwine.com/thmb/uV0O06O8WNrLepjgxkntdVuRpeE=/112x112/filters:no_upscale():max_bytes(150000):strip_icc()/brand_logo_schema-f3b2e548eb6f4243ad527798593483e0.png", "@type": "ImageObject", "width": 112, "height": 112}, "name": "Food & Wine", "@type": "Organization", "brand": "Food & Wine", "sameAs": ["https://www.facebook.com/foodandwine", "https://www.instagram.com/foodandwine/?hl=en", "https://www.pinterest.com/foodandwine/", "https://flipboard.com/@foodandwine", "https://www.youtube.com/channel/UCKH_4hkRSyUSHDIFMzlGCRA", "https://en.wikipedia.org/wiki/Food_%26_Wine"], "publishingPrinciples": "https://www.foodandwine.com/about-us-6373913#toc-editorial-policies"}, "totalTime": "PT645M", "description": "A riff on classic Spanish sangria, a traditional punch composed of wine, fruit and brandy, this recipe is made with juicy watermelon instead of apples and oranges.", "recipeYield": "8 drinks", "dateModified": "2021-04-14T17:25:26-04:00", "datePublished": "2013-12-06T18:56:23-05:00", "recipeCuisine": ["Spanish"], "recipeCategory": ["Drink", "Cocktail"], "mainEntityOfPage": {"@id": "https://www.foodandwine.com/recipes/watermelon-sangria", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.foodandwine.com/drinks", "name": "Drinks"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.foodandwine.com/cocktails", "name": "Cocktails"}, "@type": "ListItem", "position": 2}, {"item": {"@id": "https://www.foodandwine.com/cocktails-spirits/wine-cocktails", "name": "Wine cocktails"}, "@type": "ListItem", "position": 3}, {"item": {"@id": "https://www.foodandwine.com/cocktails-spirits/sangria", "name": "Sangria"}, "@type": "ListItem", "position": 4}]}}, "recipeIngredient": ["6 ounces Simple Syrup", "1 (2-inch) lemon zest strip", "1 (2-inch) orange zest strip", "2 pounds seedless watermelon, peeled and cubed, plus 1/2 pound watermelon cut into balls with a melon baller and skewered on picks", "1 bottle dry white wine", "6 ounces vodka", "4 ounces Cointreau or other triple sec", "4 ounces Citrus Syrup", "Ice"], "recipeInstructions": [{"name": "Make the Citrus Syrup", "text": "In a small saucepan, bring the Simple Syrup to a boil. Remove from the heat and add the lemon and orange zest strips. Let cool, then refrigerate overnight. Strain the syrup into an airtight container and refrigerate for up to 3 weeks.", "@type": "HowToStep"}, {"name": "Make the Sangria", "text": "In a blender, puree the watermelon cubes. Pour through a fine strainer into a pitcher. Add the white wine, vodka, Cointreau, and Citrus Syrup. Stir and refrigerate for at least 2 hours. Stir again, then pour the sangria into ice-filled white wine glasses and garnish with the skewered watermelon balls.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:52:21.536631+00:00'::timestamptz, '2026-04-25 19:25:23.403598+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:17:55.464008+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (39770, 'https://www.foodandwine.com/recipes/shochu-punch', 'foodandwine', 'Shochu Punch', 'Danielle Chang', 'https://www.foodandwine.com/thmb/3ih4F8u4Pi-hlwMPvGxQveHafi4=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/shochu-punch-FT-RECIPE0221-64f1aebff9984cc68b13938edcca2a49.jpg',  E'{"name": "Shochu Punch", "@type": ["Recipe", "NewsArticle"], "image": {"url": "https://www.foodandwine.com/thmb/3ih4F8u4Pi-hlwMPvGxQveHafi4=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/shochu-punch-FT-RECIPE0221-64f1aebff9984cc68b13938edcca2a49.jpg", "@type": "ImageObject", "width": 1500, "height": 1088}, "author": [{"url": "https://www.foodandwine.com/author/danielle-chang", "name": "Danielle Chang", "@type": "Person"}], "@context": "http://schema.org", "headline": "Shochu Punch", "publisher": {"url": "https://www.foodandwine.com", "logo": {"url": "https://www.foodandwine.com/thmb/uV0O06O8WNrLepjgxkntdVuRpeE=/112x112/filters:no_upscale():max_bytes(150000):strip_icc()/brand_logo_schema-f3b2e548eb6f4243ad527798593483e0.png", "@type": "ImageObject", "width": 112, "height": 112}, "name": "Food & Wine", "@type": "Organization", "brand": "Food & Wine", "sameAs": ["https://www.facebook.com/foodandwine", "https://www.instagram.com/foodandwine/?hl=en", "https://www.pinterest.com/foodandwine/", "https://flipboard.com/@foodandwine", "https://www.youtube.com/channel/UCKH_4hkRSyUSHDIFMzlGCRA", "https://en.wikipedia.org/wiki/Food_%26_Wine"], "publishingPrinciples": "https://www.foodandwine.com/about-us-6373913#toc-editorial-policies"}, "totalTime": "PT1495M", "description": "Danielle Chang&#39;s Shochu Punch features a variety of citrus fruits for a sour and bitter tang, jalape\\u00f1o and fresh ginger for mild heat, and buckwheat honey for lingering sweetness.", "recipeYield": "8", "dateModified": "2021-01-15T16:08:45-05:00", "datePublished": "2021-01-15T16:08:45-05:00", "recipeCuisine": ["American"], "recipeCategory": ["Dinner", "Drink"], "mainEntityOfPage": {"@id": "https://www.foodandwine.com/recipes/shochu-punch", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.foodandwine.com/drinks", "name": "Drinks"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.foodandwine.com/cocktails", "name": "Cocktails"}, "@type": "ListItem", "position": 2}]}}, "recipeIngredient": ["1 (2-inch) piece dried ginseng root (such as W Ginseng Farm)", "1 cup buckwheat honey (such as Weeks Honey Farm)", "1 cup hot water", "1 pound kumquats", "1 (750-ml.) bottle shochu", "1 (2-inch) piece fresh ginger, smashed", "1 large jalape\\u00f1o, gently smashed using flat side of a knife", ".5 cup dried goji berries (such as Navitas Organics)", ".3333 (1 1/2-x 1/2-inch) lemon peel strips, slightly pounded using mortar and pestle or flatside of a knife to release their bitter aromatics", "2 cups boiling water", ".25 cup dried chrysanthemum flower loose-leaf tea (such as Goofoo)", "Sparkling water, cucumber water (see Note), or juice of choice (optional), to taste", "1 pomelo or Ruby Red grapefruit, peeled and segmented", ".25 cup pomegranate arils", ".25 cup thinly sliced Persian cucumber"], "recipeInstructions": [{"text": "Make the shochu infusion: Add water to a medium saucepan to a depth of 1/2 inch; fit a steamer basket inside pan. Bring to a boil over high. Place dried ginseng in steamer basket. Cover pan, and reduce heat to medium; steam until ginseng is pliable, 20 to 25 minutes. Remove from heat. Transfer ginseng to a cutting board, and slice crosswise into 1/2-inch pieces; set aside.", "@type": "HowToStep"}, {"text": "While ginseng steams, stir together honey and 1 cup hot water in a small bowl until well combined. Reserve 1 cup honey mixture for chrysanthemum ice cubes; chill, covered, until ready to use. Set aside remaining 1 cup honey mixture. Place kumquats on a rimmed baking sheet. Using the bottom of a measuring cup, smash each kumquat. Transfer kumquats and any juices to a large lidded glass jar. Add shochu, ginger, jalape\\u00f1o, goji berries, lemon peel strips, reserved ginseng slices, and remaining 1 cup honey mixture to kumquats in jar; stir to combine. Secure lid on jar. Store in a cool, dark place at least 24 hours or up to 1 week, depending on your taste preference. (You should taste the shochu once per day. You should be able to taste a noticeable citrus flavor and a slight bitterness from the kumquats.)", "@type": "HowToStep"}, {"text": "Make the chrysanthemum ice cubes, if desired: Stir together 2 cups boiling water, dried chrysanthemum flowers, and reserved 1 cup honey mixture in a medium-size heatproof bowl; let cool at room temperature 1 hour. Using a slotted spoon, remove chrysanthemum flowers from mixture. Divide flowers evenly among bottom pieces of 2 (6-cube, 1 3/4-inch) ball-shaped ice cube trays. Secure trays with top pieces; pour honey mixture evenly into trays. Freeze 12 hours.", "@type": "HowToStep"}, {"text": "When ready to serve, pour desired amount of shochu infusion (the full amount serves 8) through a fine wire-mesh strainer into a small punch bowl; discard solids. If using, remove chrysanthemum ice cubes from ice cube trays, and add to punch bowl. Add sparkling water, cucumber water, or juice of choice to taste. Top punch with pomelo segments, pomegranate arils, and Persian cucumber slices. To prepare cucumber water, mix 2 cups water with 2 cups lightly smashed Persian cucumbers. Cover and refrigerate 1 hour. Strain before using.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:52:22.226775+00:00'::timestamptz, '2026-04-25 19:25:23.972041+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:17:42.046115+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (39782, 'https://www.foodandwine.com/recipes/ruby-red-spritz', 'foodandwine', 'Ruby Red Spritz', 'M. Carrie Allan', 'https://www.foodandwine.com/thmb/JcIwRbaFGRCFFxckat8UUusUCbw=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Ruby-Red-Spritz-FT-RECIPE0120-759bacaca703400f993d3ad61bf70350.jpg',  E'{"name": "Ruby Red Spritz", "@type": ["Recipe", "NewsArticle"], "image": {"url": "https://www.foodandwine.com/thmb/JcIwRbaFGRCFFxckat8UUusUCbw=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Ruby-Red-Spritz-FT-RECIPE0120-759bacaca703400f993d3ad61bf70350.jpg", "@type": "ImageObject", "width": 1500, "height": 1000}, "author": [{"url": "https://www.foodandwine.com/author/m-carrie-allan", "name": "M. Carrie Allan", "@type": "Person"}], "@context": "http://schema.org", "headline": "Ruby Red Spritz", "nutrition": {"@type": "NutritionInformation", "calories": "654 kcal", "fatContent": "2 g", "fiberContent": "17 g", "sugarContent": "84 g", "sodiumContent": "7 mg", "proteinContent": "9 g", "cholesterolContent": "0 mg", "carbohydrateContent": "128 g", "saturatedFatContent": "0 g", "unsaturatedFatContent": "0 g"}, "publisher": {"url": "https://www.foodandwine.com", "logo": {"url": "https://www.foodandwine.com/thmb/uV0O06O8WNrLepjgxkntdVuRpeE=/112x112/filters:no_upscale():max_bytes(150000):strip_icc()/brand_logo_schema-f3b2e548eb6f4243ad527798593483e0.png", "@type": "ImageObject", "width": 112, "height": 112}, "name": "Food & Wine", "@type": "Organization", "brand": "Food & Wine", "sameAs": ["https://www.facebook.com/foodandwine", "https://www.instagram.com/foodandwine/?hl=en", "https://www.pinterest.com/foodandwine/", "https://flipboard.com/@foodandwine", "https://www.youtube.com/channel/UCKH_4hkRSyUSHDIFMzlGCRA", "https://en.wikipedia.org/wiki/Food_%26_Wine"], "publishingPrinciples": "https://www.foodandwine.com/about-us-6373913#toc-editorial-policies"}, "totalTime": "PT5M", "description": "This Ruby Red Spritz recipe gets its flavor from Ruby Red grapefruit juice, Campari, and dry sparkling ros\\u00e9. Get the recipe from Food &amp; Wine.", "recipeYield": "1", "dateModified": "2020-01-01T10:13:32-05:00", "datePublished": "2019-12-30T10:13:32-05:00", "recipeCuisine": ["American"], "recipeCategory": ["Drink", "Cocktail"], "mainEntityOfPage": {"@id": "https://www.foodandwine.com/recipes/ruby-red-spritz", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.foodandwine.com/drinks", "name": "Drinks"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.foodandwine.com/cocktails", "name": "Cocktails"}, "@type": "ListItem", "position": 2}, {"item": {"@id": "https://www.foodandwine.com/gin-cocktails-7496744", "name": "Gin Cocktails"}, "@type": "ListItem", "position": 3}]}}, "recipeIngredient": ["2 tablespoons (1 ounce) dry gin", "2 tablespoons fresh Ruby Red grapefruit juice", "1 tablespoon (1/2 ounce) Campari", "4 to 6 tablespoons (2 to 3 ounces) chilled dry sparkling ros\\u00e9", "Splash of club soda (optional)", "Thyme sprig", "Thin Ruby Red grapefruit slice"], "recipeInstructions": [{"text": "Fill a large wine glass halfway with ice. Add gin, grapefruit juice, and Campari. Top with sparkling wine and, if desired, club soda, and stir gently. Smack thyme between your palms, and add to cocktail with grapefruit slice.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:52:23.709609+00:00'::timestamptz, '2026-04-25 19:25:24.528265+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:17:37.841949+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (39787, 'https://www.foodandwine.com/recipes/pineau-spritz', 'foodandwine', 'Pineau Spritz', 'Rebekah Peppler', 'https://www.foodandwine.com/thmb/EJNtyYFwf8rw2ibdYraPkKzPSXQ=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/pineau-spritz-FT-RECIPE1019-60ea57e835fc4b858d7d6e9a4cdd7cf6.jpg',  E'{"name": "Pineau Spritz", "@type": ["Recipe", "NewsArticle"], "image": {"url": "https://www.foodandwine.com/thmb/EJNtyYFwf8rw2ibdYraPkKzPSXQ=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/pineau-spritz-FT-RECIPE1019-60ea57e835fc4b858d7d6e9a4cdd7cf6.jpg", "@type": "ImageObject", "width": 1500, "height": 1125}, "author": [{"url": "https://www.foodandwine.com/author/rebekah-peppler", "name": "Rebekah Peppler", "@type": "Person"}], "@context": "http://schema.org", "headline": "Pineau Spritz", "publisher": {"url": "https://www.foodandwine.com", "logo": {"url": "https://www.foodandwine.com/thmb/uV0O06O8WNrLepjgxkntdVuRpeE=/112x112/filters:no_upscale():max_bytes(150000):strip_icc()/brand_logo_schema-f3b2e548eb6f4243ad527798593483e0.png", "@type": "ImageObject", "width": 112, "height": 112}, "name": "Food & Wine", "@type": "Organization", "brand": "Food & Wine", "sameAs": ["https://www.facebook.com/foodandwine", "https://www.instagram.com/foodandwine/?hl=en", "https://www.pinterest.com/foodandwine/", "https://flipboard.com/@foodandwine", "https://www.youtube.com/channel/UCKH_4hkRSyUSHDIFMzlGCRA", "https://en.wikipedia.org/wiki/Food_%26_Wine"], "publishingPrinciples": "https://www.foodandwine.com/about-us-6373913#toc-editorial-policies"}, "totalTime": "PT5M", "description": "The Pineau Spritz is a product of a looming ap\\u00e9ro d\\u00eenatoire and an excess of half-drunk bottles of sweet Pineau des Charentes and dry sparkling wine i...", "recipeYield": "1", "dateModified": "2019-10-01T00:39:11-04:00", "datePublished": "2019-09-19T00:39:11-04:00", "recipeCuisine": ["French Inspired", "French"], "recipeCategory": ["Drink", "Cocktail"], "mainEntityOfPage": {"@id": "https://www.foodandwine.com/recipes/pineau-spritz", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.foodandwine.com/drinks", "name": "Drinks"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.foodandwine.com/cocktails", "name": "Cocktails"}, "@type": "ListItem", "position": 2}, {"item": {"@id": "https://www.foodandwine.com/cocktails-spirits/brunch-cocktails", "name": "Brunch Cocktails"}, "@type": "ListItem", "position": 3}, {"item": {"@id": "https://www.foodandwine.com/sparkling-wine-cocktails-7496747", "name": "Sparkling Wine Cocktails"}, "@type": "ListItem", "position": 4}]}}, "recipeIngredient": ["Ice cubes", "3 tablespoons (1 1/2 ounces) Pineau des Charentes", "2 tablespoons fresh lemon juice", "1 tablespoon Honey Syrup", "2 dashes Angostura bitters", "2 (1 1/2-inch) lemon peel strips, divided", "Sparkling wine"], "recipeInstructions": [{"text": "Fill a cocktail shaker with ice; add Pineau des Charentes, lemon juice, syrup, and bitters. Hold 1 of the lemon peel strips by a long edge, skin facing down in shaker. Pinch peel strip to express citrus oils; drop into shaker. Cover and shake vigorously. Strain into an ice-filled Collins glass, top with sparkling wine, and garnish with remaining lemon peel strip.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:52:23.460713+00:00'::timestamptz, '2026-04-25 19:25:24.873155+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:17:25.187973+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (39797, 'https://www.foodandwine.com/recipes/butterflys-breath', 'foodandwine', 'Butterfly&#39;s Breath', 'Paul Child', 'https://www.foodandwine.com/thmb/V3zjhHpjQmbl6tOtXIPA0eHbytk=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/butterflys-breath-FT-RECIPE1118-4b60960c225c4631acd090e75aaf7755.jpg',  E'{"name": "Butterfly&#39;s Breath", "@type": ["Recipe", "NewsArticle"], "image": {"url": "https://www.foodandwine.com/thmb/V3zjhHpjQmbl6tOtXIPA0eHbytk=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/butterflys-breath-FT-RECIPE1118-4b60960c225c4631acd090e75aaf7755.jpg", "@type": "ImageObject", "width": 1500, "height": 1125}, "author": [{"url": "https://www.foodandwine.com/author/paul-child", "name": "Paul Child", "@type": "Person"}], "@context": "http://schema.org", "headline": "Butterfly&#39;s Breath", "nutrition": {"@type": "NutritionInformation", "calories": "218 kcal", "fatContent": "0 g", "fiberContent": "1 g", "sugarContent": "9 g", "sodiumContent": "2 mg", "proteinContent": "0 g", "cholesterolContent": "0 mg", "carbohydrateContent": "11 g", "saturatedFatContent": "0 g", "unsaturatedFatContent": "0 g"}, "publisher": {"url": "https://www.foodandwine.com", "logo": {"url": "https://www.foodandwine.com/thmb/uV0O06O8WNrLepjgxkntdVuRpeE=/112x112/filters:no_upscale():max_bytes(150000):strip_icc()/brand_logo_schema-f3b2e548eb6f4243ad527798593483e0.png", "@type": "ImageObject", "width": 112, "height": 112}, "name": "Food & Wine", "@type": "Organization", "brand": "Food & Wine", "sameAs": ["https://www.facebook.com/foodandwine", "https://www.instagram.com/foodandwine/?hl=en", "https://www.pinterest.com/foodandwine/", "https://flipboard.com/@foodandwine", "https://www.youtube.com/channel/UCKH_4hkRSyUSHDIFMzlGCRA", "https://en.wikipedia.org/wiki/Food_%26_Wine"], "publishingPrinciples": "https://www.foodandwine.com/about-us-6373913#toc-editorial-policies"}, "totalTime": "PT5M", "description": "This brandy-laced riff on a gimlet was invented by Julia Child\\u2019s husband, Paul Child. Get the recipe at Food &amp; Wine.", "recipeYield": "1 cocktail", "dateModified": "2018-11-01T09:14:32-04:00", "datePublished": "2018-10-05T09:14:32-04:00", "recipeCuisine": ["American"], "recipeCategory": ["Dinner", "Drink"], "mainEntityOfPage": {"@id": "https://www.foodandwine.com/recipes/butterflys-breath", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.foodandwine.com/drinks", "name": "Drinks"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.foodandwine.com/cocktails", "name": "Cocktails"}, "@type": "ListItem", "position": 2}, {"item": {"@id": "https://www.foodandwine.com/gin-cocktails-7496744", "name": "Gin Cocktails"}, "@type": "ListItem", "position": 3}]}}, "recipeIngredient": ["3 3/4\\u00a0teaspoons sweetened lime juice (such as Rose\\u2019s)", "1 tablespoon water", "1/2 teaspoon granulated sugar", "1/4 cup (2 ounces) London dry gin (such as Beefeater)", "2 tablespoons (1 ounce) apricot brandy", "Lemon peel twist or lime peel twist"], "recipeInstructions": [{"text": "Stir together lime juice, 1 tablespoon water, and sugar in a mixing glass until sugar is dissolved. Pour gin and apricot brandy into glass, and fill glass with ice. Using a bar spoon, stir until outside of glass is frosty, about 30 seconds. Strain into a cocktail glass. Garnish with a lemon peel twist.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:52:25.009082+00:00'::timestamptz, '2026-04-25 19:25:25.501366+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:48.728621+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (40068, 'https://www.thekitchn.com/how-to-make-cappuccino-recipe-23402948', 'thekitchn', 'How to Make a Cappuccino', 'Maria Do', 'https://cdn.apartmenttherapy.info/image/upload/f_jpg,q_auto:eco,c_fill,g_auto,w_1500,ar_16:9/k%2FPhoto%2FRecipe%20Ramp%20Up%2F2022-07-Cappuccino%2FCappuccino',  E'{"@id": "https://www.thekitchn.com/how-to-make-cappuccino-recipe-23402948/#post-recipe-349770083", "url": "https://www.thekitchn.com/how-to-make-cappuccino-recipe-23402948", "name": "How to Make a Cappuccino", "@type": "Recipe", "brand": {"name": "The Kitchn", "@type": "Thing"}, "image": [{"url": "https://cdn.apartmenttherapy.info/image/upload/f_jpg,q_auto:eco,c_fill,g_auto,w_1500,ar_16:9/k%2FPhoto%2FRecipe%20Ramp%20Up%2F2022-07-Cappuccino%2FCappuccino", "@type": "ImageObject"}, {"url": "https://cdn.apartmenttherapy.info/image/upload/f_jpg,q_auto:eco,c_fill,g_auto,w_1500,ar_4:3/k%2FPhoto%2FRecipe%20Ramp%20Up%2F2022-07-Cappuccino%2FCappuccino", "@type": "ImageObject"}, {"url": "https://cdn.apartmenttherapy.info/image/upload/f_jpg,q_auto:eco,c_fill,g_auto,w_1500,ar_1:1/k%2FPhoto%2FRecipe%20Ramp%20Up%2F2022-07-Cappuccino%2FCappuccino", "@type": "ImageObject"}], "author": [{"URL": "https://www.thekitchn.com/authors/maria-do", "name": "Maria Do", "@type": "Person", "jobTitle": "", "description": "Maria is a recipe developer and food photographer from New Orleans. Her Southern food blog, Murmurs of Ricotta, houses some of Google\\u2019s top-ranking recipes for Mardi Gras King Cake and Gouda Mac. She currently lives in Orange County, CA, where she can be found enjoying Vietnamese foods from her childhood and watching way too much Netflix. "}], "creator": {"name": "Maria Do", "@type": "Person"}, "@context": "https://schema.org", "abstract": null, "headline": "How to Make a Cappuccino", "keywords": ["beverages", "breakfast", "coffee", "dairy", "european", "italian", "nonalcoholic", "pantry", "quick", "recipe"], "prepTime": "PT5S", "nutrition": {"@type": "NutritionInformation", "calories": "91 cal", "fatContent": "3.7 g", "servingSize": "Serves 1", "fiberContent": "0.2 g", "sugarContent": "5.7 g", "sodiumContent": "53.3 mg", "proteinContent": "4.3 g", "cholesterolContent": "0 mg", "carbohydrateContent": "10.2 g", "saturatedFatContent": "2.1 g", "unsaturatedFatContent": "0.0 g"}, "publisher": {"url": "https://www.thekitchn.com", "logo": {"url": "https://www.thekitchn.com/static/logos/publisher-logo.png", "@type": "ImageObject", "width": 180, "height": 46}, "name": "The Kitchn", "@type": "NewsMediaOrganization", "brand": {"name": "The Kitchn", "@type": "Brand"}, "email": "info@thekitchn.com", "sameAs": ["https://www.facebook.com/thekitchn/", "https://www.instagram.com/thekitchn", "https://www.tiktok.com/@thekitchn", "https://www.youtube.com/channel/UCuNKgYLb0wOoMvclzSlBvbQ", "https://www.pinterest.com/thekitchn/", "https://www.apartmenttherapymedia.com/our-brands/thekitchn"], "address": {"@type": "PostalAddress", "postalCode": "10012", "addressRegion": "NY", "streetAddress": "270 Lafayette Street, Ste 1300", "addressCountry": "US", "addressLocality": "New York"}, "masthead": "https://www.thekitchn.com/team", "telephone": "212-966-7174", "description": "The Kitchn provides inspiration for the food our readers want to eat, and resources for them to become the cooks they want to be.", "parentOrganization": {"url": "https://www.apartmenttherapymedia.com", "name": "Apartment Therapy Media LLC", "@type": "Organization", "alternateName": "AT Media LLC"}}, "totalTime": "PT5S", "identifier": {"@type": "PropertyValue", "value": "349770083", "propertyID": "recipeID"}, "dateCreated": "2022-08-03T15:30:00-04:00", "description": "A smooth blend of creamy milk and strong espresso, topped with a tall layer of soft milk foam.", "recipeYield": 1, "dateModified": "2022-08-03T15:30:00-04:00", "thumbnailUrl": "https://cdn.apartmenttherapy.info/image/upload/f_auto,q_auto:eco,c_fill,g_auto,w_1500,ar_3:2/k%2FPhoto%2FRecipe%20Ramp%20Up%2F2022-07-Cappuccino%2FCappuccino", "datePublished": "2022-08-03T15:30:00-04:00", "recipeCuisine": ["Italian", "Europe"], "articleSection": "Recipes", "recipeCategory": ["Breakfast", "Beverage", "Coffee", "Brunch"], "mainEntityOfPage": "https://www.thekitchn.com/how-to-make-cappuccino-recipe-23402948", "recipeIngredient": ["2 tablespoons finely ground dark roast coffee beans", "2 ounces (1/4 cup) water", "4 ounces (1/2 cup) whole milk or unsweetened oat milk", "1/8 teaspoon cocoa powder or ground cinnamon, for dusting (optional)"], "recipeInstructions": [{"url": "https://www.thekitchn.com/how-to-make-cappuccino-recipe-23402948#step-349770083-instructiongroup-1-1", "name": "Step 1", "text": "Make 2 shots of espresso in an espresso machine: Add 2 ounces (1/4 cup) water to the boiler, then firmly pack 2 tablespoons (2 shots) finely ground dark coffee beans into the portafilter. Attach the portafilter to the machine and place a cup or carafe underneath the drip spout. Turn the espresso machine on and brew the espresso, 25 to 45 seconds depending on your machine. Pour the espresso into a coffee cup.", "@type": "HowToStep", "image": null}, {"url": "https://www.thekitchn.com/how-to-make-cappuccino-recipe-23402948#step-349770083-instructiongroup-1-2", "name": "Step 2", "text": "Make the steamed milk and foam: Pour 4 ounces (1/2 cup) whole or unsweetened oat milk into a small pitcher. Using the steam wand on the espresso machine, hold the milk pitcher so the wand nozzle is just below the surface of the milk and  against the side of the pitcher. Turn on the wand and froth the milk until it doubles in volume, moving the pitcher higher and lower so the wand can evenly foam the milk, 60 to 90 seconds. The bubbles should get smaller in size.", "@type": "HowToStep", "image": null}, {"url": "https://www.thekitchn.com/how-to-make-cappuccino-recipe-23402948#step-349770083-instructiongroup-1-3", "name": "Step 3", "text": "Swirl the foamed milk in the pitcher. Pour the foamed milk over the brewed espresso until the foam reaches the brim of the cup. Half of the milk will settle while the foam sits on top. Lightly dust the top with 1/8 teaspoon cocoa powder or ground cinnamon if desired.", "@type": "HowToStep", "image": null}, {"name": "Recipe Notes", "@type": "HowToSection", "itemListElement": [{"text": "Steamed milk + foam without an espresso machine wand: If you don\\u2019t have a steam wand, warm the milk in a saucepan until it reaches 150\\u00baF. Use a handheld frother to create foam until the milk volume doubles in size. If you don&#x27;t have a handheld frother, you can also use a whisk and whip by hand until you can get the bubbles as small as you can.Milk substitutes: Whole milk is best for the foam cap because the fat content makes frothing easier. Half-and-half, heavy cream, or unsweetened oat milk can also be used with great results. Do not use 2% or skim milk, as they will not foam well.", "@type": "HowToTip"}]}]}'::jsonb, '2026-04-23 21:51:35.770560+00:00'::timestamptz, '2026-04-25 19:25:34.562163+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:17:01.011669+00:00'::timestamptz, NULL, NULL, NULL);
