 {"@type": "NutritionInformation", "calories": "271 cal", "fatContent": "11.4 g", "servingSize": "Serves 8", "fiberContent": "0.1 g", "sugarContent": "6.5 g", "sodiumContent": "40.5 mg", "proteinContent": "10.2 g", "cholesterolContent": "0 mg", "carbohydrateContent": "18.7 g", "saturatedFatContent": "10.1 g", "unsaturatedFatContent": "0.0 g"}, "publisher": {"url": "https://www.thekitchn.com", "logo": {"url": "https://www.thekitchn.com/static/logos/publisher-logo.png", "@type": "ImageObject", "width": 180, "height": 46}, "name": "The Kitchn", "@type": "NewsMediaOrganization", "brand": {"name": "The Kitchn", "@type": "Brand"}, "email": "info@thekitchn.com", "sameAs": ["https://www.facebook.com/thekitchn/", "https://www.instagram.com/thekitchn", "https://www.tiktok.com/@thekitchn", "https://www.youtube.com/channel/UCuNKgYLb0wOoMvclzSlBvbQ", "https://www.pinterest.com/thekitchn/", "https://www.apartmenttherapymedia.com/our-brands/thekitchn"], "address": {"@type": "PostalAddress", "postalCode": "10012", "addressRegion": "NY", "streetAddress": "270 Lafayette Street, Ste 1300", "addressCountry": "US", "addressLocality": "New York"}, "masthead": "https://www.thekitchn.com/team", "telephone": "212-966-7174", "description": "The Kitchn provides inspiration for the food our readers want to eat, and resources for them to become the cooks they want to be.", "parentOrganization": {"url": "https://www.apartmenttherapymedia.com", "name": "Apartment Therapy Media LLC", "@type": "Organization", "alternateName": "AT Media LLC"}}, "totalTime": "PT0S", "identifier": {"@type": "PropertyValue", "value": "10658", "propertyID": "recipeID"}, "dateCreated": "2016-10-25T09:00:00-04:00", "description": "", "recipeYield": 8, "dateModified": "2020-01-29T10:27:48-05:00", "thumbnailUrl": "https://cdn.apartmenttherapy.info/image/upload/f_auto,q_auto:eco,c_fill,g_auto,w_1500,ar_3:2/k%2Farchive%2F5690f92deaad394fda82770a23d218bd79311e69", "datePublished": "2016-10-25T09:00:00-04:00", "recipeCuisine": [], "articleSection": "Recipes", "recipeCategory": ["Sweets", "Candy", "Beverage", "Cocktail", "Punch"], "suitableforDiet": "https://schema.org/GlutenFreeDiet,https://schema.org/LowCalorieDiet,https://schema.org/LowFatDiet", "mainEntityOfPage": "https://www.thekitchn.com/recipe-layered-candy-corn-punch-236801", "recipeIngredient": ["1  (3-ounce) package lemon-flavored gelatin dessert", "1/4 cup boiling water", "1 cup vodka, divided", "1 1/4 cups mango nectar", "2 3/4 cups orange soda, chilled", "1  (15-ounce) can full-fat coconut milk, chilled overnight", "1 tablespoon granulated sugar", "  Candy corn, for garnish"], "recipeInstructions": [{"url": "https://www.thekitchn.com/recipe-layered-candy-corn-punch-236801#step-10658-instructiongroup-1-1", "name": "Step 1", "text": "Combine the gelatin and water in a large bowl, stirring until gelatin is dissolved. Stir in 1/2 cup of the vodka and the mango nectar. Pour the mixture into a tall, clear 2-quart pitcher. Cover and chill until thickened but not set, about 2 hours.", "@type": "HowToStep", "image": null}, {"url": "https://www.thekitchn.com/recipe-layered-candy-corn-punch-236801#step-10658-instructiongroup-1-2", "name": "Step 2", "text": "Stir the remaining 1/2 cup vodka and orange soda together in a medium bowl or measuring cup. Press a large spoon against the side of the pitcher and gently pour over the back of spoon on top of gelatin layer.", "@type": "HowToStep", "image": null}, {"url": "https://www.thekitchn.com/recipe-layered-candy-corn-punch-236801#step-10658-instructiongroup-1-3", "name": "Step 3", "text": "Open the can of coconut milk, scoop out the firm layer of cream that has solidified at the top, and place in a bowl. (Save the rest of the can for another use.) Add the sugar and beat with an electric mixer until soft peaks form, 3 to 5 minutes. Spoon over the mixture in the pitcher. Garnish with the candy corn and serve.", "@type": "HowToStep", "image": null}]}'::jsonb, '2026-04-23 21:51:58.218860+00:00'::