insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (40269, 'https://www.marthastewart.com/332441/mulled-wine', 'marthastewart', 'Mulled Wine', 'Martha Stewart', 'https://www.marthastewart.com/thmb/rdy9DS-Ib96QpE8AT-A1Nfc3lVk=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/MS-332441-mulled-wine-hero-7211-541c12ab7a0347f59d9f6bcd7044d0d9.jpg', '{"name": "Mulled Wine", "@type": ["Recipe"], "image": {"url": "https://www.marthastewart.com/thmb/rdy9DS-Ib96QpE8AT-A1Nfc3lVk=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/MS-332441-mulled-wine-hero-7211-541c12ab7a0347f59d9f6bcd7044d0d9.jpg", "@type": "ImageObject", "width": 1500, "height": 1000}, "author": [{"url": "https://www.marthastewart.com/author/martha-stewart", "name": "Martha Stewart", "@type": "Person"}], "review": [{"@type": "Review", "author": {"name": "Brenda", "@type": "Person"}, "reviewBody": "No changed delicious as the recipe says. Thank you Martha.", "reviewRating": {"@type": "Rating", "ratingValue": "5"}, "datePublished": "2026-02-17T16:38:42.275Z"}, {"@type": "Review", "author": {"name": "Katherine", "@type": "Person"}, "reviewBody": "In the winter, I love to serve hot beverages in crockpots for everyone to serve themselves. I followed this recipe, but cheated by using Williams Sonoma Mulling spices which contain the same spices as described but are already mixed. My guests loved it and we''re drinking the leftovers!", "reviewRating": {"@type": "Rating", "ratingValue": "5"}, "datePublished": "2025-12-18T05:35:23.791Z"}], "@context": "http://schema.org", "headline": "Mulled Wine", "keywords": "Christmas, Fall, Infuse, Mulled wines, Red wines, Religious celebrations, Spices, Thanksgiving, Winter", "prepTime": "PT15M", "publisher": {"url": "https://www.marthastewart.com", "logo": {"url": "https://www.marthastewart.com/thmb/OrGf7M7NNCLRjtC4UMQrre8Dbzk=/640x640/filters:no_upscale():max_bytes(150000):strip_icc()/martha_stewart_logo_schema-d4d4988b043746a298d19488f9a6803d.png", "@type": "ImageObject", "width": 640, "height": 640}, "name": "Martha Stewart", "@type": "Organization", "brand": "Martha Stewart", "sameAs": ["https://www.facebook.com/marthastewart/", "https://www.instagram.com/marthastewart/", "https://www.pinterest.com/marthastewart/", "https://www.youtube.com/user/marthastewart/", "https://www.tiktok.com/@marthastewartliving", "https://flipboard.com/@marthastewartliving", "https://en.wikipedia.org/wiki/Martha_Stewart_Living", "https://www.facebook.com/MarthaStewartWeddings/", "https://www.instagram.com/martha_weddings", "https://www.pinterest.com/MarthaWeddings/", "https://www.youtube.com/MarthaWeddings", "https://www.youtube.com/everydayfood"], "publishingPrinciples": "https://www.marthastewart.com/about-marthastewart-com-7104054#toc-editorial-guidelines"}, "totalTime": "PT45M", "contributor": [{"url": "https://www.marthastewart.com/victoria-spencer-7106333", "name": "Victoria Spencer", "@type": "Person"}], "description": "Our mulled wine recipe is an easy holiday classic. Red wine is heated with spices, orange, and brandy for a richly scented, warm and cozy beverage.", "recipeYield": "4", "dateModified": "2024-12-12T10:29:32.220-05:00", "datePublished": "2011-02-10T06:10:25.000-05:00", "recipeCuisine": ["British"], "recipeCategory": ["Beverage"], "aggregateRating": {"@type": "AggregateRating", "ratingCount": "221", "ratingValue": "4.1"}, "mainEntityOfPage": {"@id": "https://www.marthastewart.com/332441/mulled-wine", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.marthastewart.com/1509043/food-cooking", "name": "Food & Cooking"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.marthastewart.com/1505788/recipes", "name": "Recipes"}, "@type": "ListItem", "position": 2}, {"item": {"@id": "https://www.marthastewart.com/1502304/drink-recipes", "name": "Drink Recipes"}, "@type": "ListItem", "position": 3}]}}, "recipeIngredient": ["1 large orange", "2 cardamom pods", "6 whole clove", "6 allspice berries", "6 whole black peppercorns", "1 cinnamon stick, plus 4 for garnish (optional)", "1 bottle (3 cups) fruity red wine", "0.5 cup sugar", "0.25 cup brandy", "4 cinnamon sticks for garnish (optional)"], "recipeInstructions": [{"name": "Zest and juice orange:", "text": "Using a microplane or fine grater, zest the orange. Then juice it.", "@type": "HowToStep", "image": [{"url": "https://www.marthastewart.com/thmb/T0FCQ_C7jEzDqK3vH913DacXUf4=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/MS-332441-mulled-wine-01-7076-786805ca698a47c89ef5aa3c80619efd.jpg", "@type": "ImageObject"}]}, {"name": "Bruise cardamom pods:", "text": "With the flat side of a knife, press firmly on the cardamom pods to bruise them.", "@type": "HowToStep", "image": [{"url": "https://www.marthastewart.com/thmb/8XY-7xhgGCNANO9oFsJxz9aCX0o=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/MS-332441-mulled-wine-02-7087-b6d5cc7140c14fb2a71f76c06e91ca1c.jpg", "@type": "ImageObject"}]}, {"name": "Heat mulled wine:", "text": "In a large pot, combine zest, juice, spices, wine, sugar, and brandy. Cook over medium heat, stirring, until sugar dissolves, 1 to 2 minutes. Reduce heat to low; simmer until flavors have melded, about 30 minutes.", "@type": "HowToStep", "image": [{"url": "https://www.marthastewart.com/thmb/cLN6CDxNDdMpOvnEUnxZKQ9FVm4=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/MS-332441-mulled-wine-03-7098-0ce74b72e54841a4a515a1066f22217c.jpg", "@type": "ImageObject"}]}, {"name": "Strain, garnish, and serve", "text": "Pour through a fine-mesh sieve to remove spices; garnish each glass with a cinnamon stick if desired, and serve immediately.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:39:17.052431+00:00'::timestamptz, '2026-04-25 19:25:40.219910+00:00'::timestamptz, 'Mulled Wine', 'alias', 'v1', '2026-05-03 23:17:13.617991+00:00'::timestamptz, NULL, 'f70340c3c01635dd4f32199860a1c386ddb1efc7690a3c0a41d84a3c99130883', 'v1');
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (40365, 'https://www.marthastewart.com/355427/lemon-drop-champagne-punch', 'marthastewart', 'Lemon Drop Champagne Punch', 'Martha Stewart', 'https://www.marthastewart.com/thmb/uACE2ZZwejsdA34IkmDWeh6UkU8=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/mla102556_1206_punch_vert-28ddae93cbc4404e839b3361bc737cfb.jpgitokTVubXQXn', '{"name": "Lemon Drop Champagne Punch", "@type": ["Recipe"], "image": {"url": "https://www.marthastewart.com/thmb/uACE2ZZwejsdA34IkmDWeh6UkU8=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/mla102556_1206_punch_vert-28ddae93cbc4404e839b3361bc737cfb.jpgitokTVubXQXn", "@type": "ImageObject", "width": 300, "height": 375}, "author": [{"url": "https://www.marthastewart.com/author/martha-stewart", "name": "Martha Stewart", "@type": "Person"}], "review": [{"@type": "Review", "author": {"name": "SteadyMug3318", "@type": "Person"}, "reviewBody": "If you like lemon, this punch is absolutely delish!!! I served this for my daughter''s bridal shower, and it was such a hit! Be careful, however, as this lemon drop champagne cocktail packs a powerful punch!!!", "reviewRating": {"@type": "Rating", "ratingValue": "5"}, "datePublished": "2023-09-21T18:06:28.363Z"}, {"@type": "Review", "author": {"name": "Martha Stewart Member", "@type": "Person"}, "reviewBody": "This punch is amazing. It''s become part of our holiday tradition. Yes, it''s time consuming and expensive to put together, but do NOT change a thing. Do not take any shortcuts or make any substitutions. It is perfection as written.", "reviewRating": {"@type": "Rating", "ratingValue": "5"}, "datePublished": "2011-07-03T05:24:45.000Z"}], "@context": "http://schema.org", "headline": "Lemon Drop Champagne Punch", "keywords": "Champagne, Cocktail party, Dinner party, Lemons, Punches, Vodka", "publisher": {"url": "https://www.marthastewart.com", "logo": {"url": "https://www.marthastewart.com/thmb/OrGf7M7NNCLRjtC4UMQrre8Dbzk=/640x640/filters:no_upscale():max_bytes(150000):strip_icc()/martha_stewart_logo_schema-d4d4988b043746a298d19488f9a6803d.png", "@type": "ImageObject", "width": 640, "height": 640}, "name": "Martha Stewart", "@type": "Organization", "brand": "Martha Stewart", "sameAs": ["https://www.facebook.com/marthastewart/", "https://www.instagram.com/marthastewart/", "https://www.pinterest.com/marthastewart/", "https://www.youtube.com/user/marthastewart/", "https://www.tiktok.com/@marthastewartliving", "https://flipboard.com/@marthastewartliving", "https://en.wikipedia.org/wiki/Martha_Stewart_Living", "https://www.facebook.com/MarthaStewartWeddings/", "https://www.instagram.com/martha_weddings", "https://www.pinterest.com/MarthaWeddings/", "https://www.youtube.com/MarthaWeddings", "https://www.youtube.com/everydayfood"], "publishingPrinciples": "https://www.marthastewart.com/about-marthastewart-com-7104054#toc-editorial-guidelines"}, "totalTime": "PT0M", "description": "Lemon complements just about everything beautifully, making it the logical flavor choice for a celebratory Champagne and vodka punch.", "recipeYield": "8", "dateModified": "2019-01-22T12:27:37.000-05:00", "datePublished": "2011-01-26T09:43:08.000-05:00", "aggregateRating": {"@type": "AggregateRating", "ratingCount": "373", "ratingValue": "3.7"}, "mainEntityOfPage": {"@id": "https://www.marthastewart.com/355427/lemon-drop-champagne-punch", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.marthastewart.com/1509043/food-cooking", "name": "Food & Cooking"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.marthastewart.com/1505788/recipes", "name": "Recipes"}, "@type": "ListItem", "position": 2}, {"item": {"@id": "https://www.marthastewart.com/1502304/drink-recipes", "name": "Drink Recipes"}, "@type": "ListItem", "position": 3}]}}, "recipeIngredient": ["3 lemons, room temperature", "0.5 cup sugar", "1 bottle (750 milliliters) Champagne, chilled", "0.75 cup best-quality vodka, chilled", "4 ounces candied lemon peels"], "recipeInstructions": [{"text": "With a vegetable peeler, remove zest from each lemon in a long, continuous spiral. Juice lemons, and strain pulp (you should have 3/4 cup juice). Set aside.", "@type": "HowToStep"}, {"text": "Heat sugar and 1/2 cup water in a small saucepan over medium-high heat, stirring until sugar has dissolved. Bring to a boil. Remove from heat. Add zest. Let syrup cool completely, about 2 hours.", "@type": "HowToStep"}, {"text": "Pour Champagne, vodka, lemon juice, and syrup into a punch bowl; stir. Serve glasses of punch with candied peels.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:39:25.677016+00:00'::timestamptz, '2026-04-25 19:25:43.852314+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:17:06.074410+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (40489, 'https://www.simplyrecipes.com/recipes/coquito_puerto_rican_coconut_eggnog/', 'simplyrecipes', 'Coquito (Puerto Rican Coconut Eggnog)', 'Garrett McCord', 'https://www.simplyrecipes.com/thmb/Z4xj-1nNaazAcAPIfCjHcw7T9d4=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/__opt__aboutcom__coeus__resources__content_migration__simply_recipes__uploads__2017__11__2017-12-Coquito-2-9cfae4c6f0794ce2aba82ae656ca6fbe.jpg',  E'{"name": "Coquito (Puerto Rican Coconut Eggnog)", "@type": ["Recipe"], "image": {"url": "https://www.simplyrecipes.com/thmb/Z4xj-1nNaazAcAPIfCjHcw7T9d4=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/__opt__aboutcom__coeus__resources__content_migration__simply_recipes__uploads__2017__11__2017-12-Coquito-2-9cfae4c6f0794ce2aba82ae656ca6fbe.jpg", "@type": "ImageObject", "width": 1500, "height": 1000}, "video": {"name": "Coquito", "@type": "VideoObject", "duration": "PT1M", "contentUrl": "https://content.jwplatform.com/videos/zVbKdaMO-px9BSfP1.mp4", "uploadDate": "2021-01-20T17:59:27.320-05:00", "description": "Think of Coquito as the Puerto Rican version of eggnog! Made with a blend of coconut ingredients, cinnamon, and rum. One batch makes plenty for a party.", "thumbnailUrl": "https://cdn.jwplayer.com/v2/media/zVbKdaMO/poster.jpg?width=1280"}, "author": [{"url": "https://www.simplyrecipes.com/garrett-mccord-5091781", "name": "Garrett McCord", "@type": "Person"}], "review": [{"@type": "Review", "author": {"name": "N Colon", "@type": "Person"}, "reviewBody": "Thank you, finally someone lets me know the simmer time. I was trying to do this by memory from watching my mom and aunts make it before, and I remembered it being on the stove for a bit.\\nI looked up 4 recipes before you, none had the cooking part.", "reviewRating": {"@type": "Rating", "ratingValue": "5"}}, {"@type": "Review", "author": {"name": "Belinda jones ", "@type": "Person"}, "reviewBody": "Love this rate 5 in taste and satisfaction."}, {"@type": "Review", "author": {"name": "B Gilbert", "@type": "Person"}, "reviewBody": "A few years ago, when I was away from home at Christmas with no means of making a Coquito, I bought a quart of eggnog from the supermarket and mixed it with a can of coconut milk. It wasn&#x27;t exactly a coquito but close enough. Eggnog has always been on the verge of being too sweet for my tastes, so this was more suited to me."}, {"@type": "Review", "author": {"name": "Melanie", "@type": "Person"}, "reviewBody": "Any tips on preventing it from seperating when in the fridge? Ive made it before but its almost like I have to blend after letting it sit to chill."}, {"@type": "Review", "author": {"name": "Dianne M Harrell ", "@type": "Person"}, "reviewBody": "so I made on the regular way as I always do and it was delicious. I also made one without any coconut no milk or cream, I used oat milk 15 oz and heavy whipping cream about 15 oz (I use the cans from the coconut cream and coconut milk to measure) I thought it was going to be harder.. I also put chocolate chip pieces in the bottle with some vanilla and some nutmeg and some peanut butter liquor(Screwball). I don&#x27;t even like Screwball but this tastes great. And I only made it for my best guy friend because his girlfriend cannot have coconut and I didn&#x27;t want to leave her out of getting a bottle. I highly recommend it if you can&#x27;t have coconut or don&#x27;t like coconut use what was in this recipe it&#x27;s amazing.", "reviewRating": {"@type": "Rating", "ratingValue": "5"}}], "@context": "http://schema.org", "cookTime": "PT35M", "headline": "Coquito (Puerto Rican Coconut Eggnog)", "keywords": "Make-ahead, Latin American, Puerto Rican, Drink, Christmas, Holiday, New Year''s", "prepTime": "PT5M", "nutrition": {"@type": "NutritionInformation", "calories": "572 kcal", "fatContent": "34 g", "servingSize": "6 to 10 servings", "fiberContent": "1 g", "sugarContent": "37 g", "sodiumContent": "150 mg", "proteinContent": "9 g", "cholesterolContent": "80 mg", "carbohydrateContent": "40 g", "saturatedFatContent": "24 g", "unsaturatedFatContent": "0 g"}, "publisher": {"url": "https://www.simplyrecipes.com", "logo": {"url": "https://www.simplyrecipes.com/thmb/QvixEwCD02s_lnkgkVb6mHwKS7c=/1125x320/filters:no_upscale():max_bytes(150000):strip_icc()/SimplyRecipesLogoTransparent-07a297c54b2142ae9c079abb2f0fa639.png", "@type": "ImageObject", "width": 1125, "height": 320}, "name": "Simply Recipes", "@type": "Organization", "brand": "Simply Recipes", "sameAs": ["https://www.facebook.com/simplyrecipes", "https://www.instagram.com/simplyrecipes", "https://www.pinterest.com/simplyrecipes"], "publishingPrinciples": "https://www.simplyrecipes.com/about-us-5096129#toc-editorial-guidelines"}, "totalTime": "PT40M", "description": "Coquito is a Puerto Rican holiday punch that&#39;s rich and sweet with coconut, plus a kiss of cinnamon and rum. One batch makes plenty for a party. Give it a try instead of eggnog!", "recipeYield": "10", "dateModified": "2025-10-26T20:45:10.524-04:00", "datePublished": "2019-11-21T13:04:30.000-05:00", "recipeCuisine": ["Latin American", "Puerto Rican"], "recipeCategory": ["Drink", "Make-ahead"], "aggregateRating": {"@type": "AggregateRating", "ratingCount": "6", "ratingValue": "4.7"}, "mainEntityOfPage": {"@id": "https://www.simplyrecipes.com/recipes/coquito_puerto_rican_coconut_eggnog/", "@type": ["WebPage"], "breadcrumb": {"@type": "BreadcrumbList", "itemListElement": [{"item": {"@id": "https://www.simplyrecipes.com/recipes-5090746", "name": "Recipes"}, "@type": "ListItem", "position": 1}, {"item": {"@id": "https://www.simplyrecipes.com/drink-recipes-5091323", "name": "Drinks"}, "@type": "ListItem", "position": 2}]}}, "recipeIngredient": ["1 (14-ounce) can sweetened condensed milk", "1 (15-ounce) can cream of coconut (like Coco Lopez or Goya)", "1 (12-ounce) can evaporated milk", "1 (13.5-ounce) can of coconut milk", "2 teaspoons vanilla, or 1 vanilla bean, split and seeded", "2 whole cinnamon sticks", "1/2 teaspoon grated nutmeg", "1 to 2 cups rum", "Grated nutmeg or ground cinnamon for garnish (optional)"], "recipeInstructions": [{"name": "Steep the spices:", "text": "Place the sweetened condensed milk, cream of coconut, evaporated milk, coconut milk, vanilla, cinnamon sticks, and nutmeg (all the ingredients except the rum) in a large saucepan. Warm over medium-high heat until just starting to simmer. Remove from heat, cover, and let infuse for 30 minutes.", "@type": "HowToStep", "image": [{"url": "https://www.simplyrecipes.com/thmb/gLgRDm9cpnaILNXZjXpaZvyF_Ak=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/__opt__aboutcom__coeus__resources__content_migration__simply_recipes__uploads__2017__11__2017-12-Coquito-1-abd974c6f89847afb12d5893c1bb2649.jpg", "@type": "ImageObject"}]}, {"name": "Mix in the rum:", "text": "Remove the cinnamon sticks and the vanilla bean (if using) and pour the mixture into a punch bowl or pitcher. (Note: I rinse and dry the vanilla bean and cinnamon sticks, and save them future infusions such as rice pudding .) Add 1 cup of rum and taste; add more rum for a stronger punch. I usually stick to around 2 cups as I prefer it strong.", "@type": "HowToStep"}, {"name": "Chill:", "text": "Chill this in the fridge for at least 2 hours or for up to 3 days.", "@type": "HowToStep"}, {"name": "Serve:", "text": "Serve neat or over ice in small portions. Garnish with grated nutmeg or ground cinnamon as desired. Did you love the recipe? How do you like to make coquito? Tell us all about it in the comments!", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:45:33.695260+00:00'::timestamptz, '2026-04-25 19:25:48.723037+00:00'::timestamptz, 'Coquito', 'alias', 'v1', '2026-05-03 23:16:50.806838+00:00'::timestamptz, NULL, 'bfb9c45787e2f9724ff01a30bec71e873a55a7f0041dbcd83697e67a8d1f5f00', 'v1');
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (40654, 'https://www.tastingtable.com/1320658/frozen-nutella-mudslide-cocktail-recipe/', 'tastingtable', 'Frozen Nutella Mudslide Cocktail Recipe', 'Michelle McGlinn', 'https://www.tastingtable.com/img/gallery/frozen-nutella-mudslide-cocktail-recipe/intro-1687445808.jpg',  E'{"name": "Frozen Nutella Mudslide Cocktail Recipe", "@type": "Recipe", "image": "https://www.tastingtable.com/img/gallery/frozen-nutella-mudslide-cocktail-recipe/intro-1687445808.jpg", "video": {"name": "Frozen Nutella Mudslide Cocktail Recipe", "@type": "VideoObject", "contentUrl": "https://www.youtube.com/watch?v=wTchEDOz47Y", "uploadDate": "2023-06-22T00:00:00+00:00", "description": "This boozy mudslide is a blend of vodka, Irish cream, coffee liqueur, Nutella, and vanilla ice cream you&#39;ll love on a summer day.", "thumbnailUrl": ["https://www.tastingtable.com/img/gallery/frozen-nutella-mudslide-cocktail-recipe/intro-1687445808.jpg"]}, "author": [{"url": "https://www.tastingtable.com/author/michellemcglinn/", "name": "Michelle McGlinn", "@type": "Person", "sameAs": ["https://www.instagram.com/michellemcglinn"], "alumniOf": [{"name": "Kent State University", "@type": "Organization"}, {"name": "Paris American Academy", "@type": "Organization"}], "knowsAbout": ["Slow-Roasted Meats", "30-Minute Meals", "Craft Cocktails"], "description": "Michelle is a professional food stylist, photographer, and recipe developer who specializes in home-cooked, rustic, and easy meals. She has experience in commercial food styling with national brands and photographs for local businesses and restauranteurs."}, {"url": "https://www.tastingtable.com/author/tastingtable/", "name": "Tasting Table Staff", "@type": "Person"}], "@context": "https://schema.org", "cookTime": "PT5M", "keywords": "quick, easy, frozen, milkshake, bailey&#39;s, kahlua, irish cream, coffee liqueur, nutella, chocolate, hazelnut, ice cream, vanilla", "prepTime": "PT5M", "nutrition": {"@type": "NutritionInformation", "calories": "1359 calories", "fatContent": "62 g fat", "servingSize": "653 g", "fiberContent": "10 g fiber", "sugarContent": "126 g ", "sodiumContent": "224 mg ", "proteinContent": "15 g protein", "transFatContent": "0 g ", "cholesterolContent": "84 mg cholesterol", "carbohydrateContent": "151 g carbohydrates", "saturatedFatContent": "51 g saturated fat"}, "totalTime": "PT10M", "description": "This boozy mudslide is a blend of vodka, Irish cream, coffee liqueur, Nutella, and vanilla ice cream you&#39;ll love on a summer day.", "recipeYield": [1, "1 Cocktail"], "datePublished": "2023-06-24T13:30:38+00:00", "recipeCuisine": "American, Caribbean", "recipeCategory": "drinks, cocktails, dessert", "aggregateRating": {"@type": "AggregateRating", "ratingCount": "35", "ratingValue": "4.9"}, "recipeIngredient": ["1 ounce milk", "2 tablespoons Nutella", "1 tablespoon Nutella sauce, for drizzling", "4 (2-inch) scoops vanilla ice cream (about 1 cup)", "1 cup ice", "\\u00bc cup Nutella", "1 ounce vodka", "1 ounce coffee liqueur", "1 ounce Irish cream liqueur", "1/2 cup Whipped cream, for topping", "1 Pirouette cookie, for serving", "1 tablespoons cocoa powder, for dusting"], "recipeInstructions": [{"text": "To make the sauce, heat the milk in a microwave-safe bowl for 30 seconds to warm. Whisk in 2 tablespoons of Nutella until smooth and saucy. Set aside.", "@type": "HowToStep"}, {"text": "Fill a blender with ice cream, ice, Nutella, vodka, coffee liqueur, and Irish cream liqueur. Working quickly, cover the blender and blend until smooth. Mixture should be the consistency of a milkshake.", "@type": "HowToStep"}, {"text": "Using a squeeze bottle or a thin spoon, drizzle the Nutella sauce around the inside of a Sundae glass. Pour the blended mudslide into the glass. Top with whipped cream, dusting lightly with cocoa powder. Garnish with a Pirouette cookie.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:46:15.510242+00:00'::timestamptz, '2026-04-25 19:25:52.115793+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:56.571655+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (40742, 'https://www.tastingtable.com/1612209/watermelon-lime-agua-fresca-recipe/', 'tastingtable', 'Watermelon Lime Agua Fresca Recipe', 'Taylor Murray', 'https://www.tastingtable.com/img/gallery/watermelon-lime-agua-fresca-recipe/intro-1719590468.jpg',  E'{"name": "Watermelon Lime Agua Fresca Recipe", "@type": "Recipe", "image": "https://www.tastingtable.com/img/gallery/watermelon-lime-agua-fresca-recipe/intro-1719590468.jpg", "video": {"name": "Watermelon Lime Agua Fresca Recipe", "@type": "VideoObject", "contentUrl": "https://youtu.be/daTvA4bLn7U", "uploadDate": "2024-06-28T19:37:29+00:00", "description": "Agua fresca is a classic summertime drink, and this easy, 10-minute, and 2-ingredients version features summery watermelon and a splash of lime juice.", "thumbnailUrl": ["https://www.tastingtable.com/img/gallery/watermelon-lime-agua-fresca-recipe/intro-1719590468.jpg"]}, "author": [{"url": "https://www.tastingtable.com/author/taylormurray/", "name": "Taylor Murray", "@type": "Person", "sameAs": ["https://www.linkedin.com/in/taylorelysemurray/", "https://muckrack.com/taylor-murray-1"], "alumniOf": [{"name": "Johnson and Wales University", "@type": "Organization"}, {"name": "Bennington College", "@type": "Organization"}], "knowsAbout": ["Michelin-Level Restaurants", "Farm-to-Table Cooking", "Los Angeles Restaurants"], "description": "Taylor is a California born-and-raised freelance writer and recipe developer with over a dozen years of professional cooking experience. She worked her way up from the bottom as a young cook, eventually going on to work at Michelin and James Beard award-winning restaurants such as Fruition, Frasca Food and Wine, and Eleven Madison Park."}], "@context": "https://schema.org", "keywords": "2-ingredient, easy, picnic, party, cookout, summer, fruit, quick, 10-minute, blended", "prepTime": "PT10M", "nutrition": {"@type": "NutritionInformation", "calories": "16 calories", "fatContent": "0 g fat", "servingSize": "53 g", "fiberContent": "0 g fiber", "sugarContent": "3 g ", "sodiumContent": "1 mg ", "proteinContent": "0 g protein", "transFatContent": "0 g ", "cholesterolContent": "0 mg cholesterol", "carbohydrateContent": "4 g carbohydrates", "saturatedFatContent": "0 g saturated fat"}, "totalTime": "PT10M", "description": "Agua fresca is a classic summertime drink, and this easy, 10-minute, and 2-ingredients version features summery watermelon and a splash of lime juice.", "recipeYield": [2, "2 quarts"], "datePublished": "2024-06-28T20:30:40+00:00", "recipeCuisine": "Mexican, Latin American", "recipeCategory": "drink, gluten-free, vegetarian, vegan", "aggregateRating": {"@type": "AggregateRating", "ratingCount": "39", "ratingValue": "4.9"}, "recipeIngredient": ["1 (10-pound) watermelon", "3 limes"], "recipeInstructions": [{"text": "Cut the rind off of the watermelon.", "@type": "HowToStep"}, {"text": "Cut the melon into large chunks.", "@type": "HowToStep"}, {"text": "Transfer the melon to a blender \\u2014 in batches, if needed \\u2014 and blend until smooth.", "@type": "HowToStep"}, {"text": "Strain through a fine mesh strainer, then repeat with remaining watermelon chunks.", "@type": "HowToStep"}, {"text": "Juice the limes into the blended watermelon and (optionally) add a pinch of salt.", "@type": "HowToStep"}, {"text": "Pour over ice and serve with additional slices of lime, if desired.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:47:22.406963+00:00'::timestamptz, '2026-04-25 19:25:53.291566+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:17:55.464008+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (41151, 'https://www.tastingtable.com/688145/big-apple-cocktail-recipe-a-manhattan/', 'tastingtable', 'Big Apple Cocktail Recipe, A Manhattan | Tasting Table', 'Tasting Table Staff', 'https://www.tastingtable.com/img/gallery/Big-Apple-Cocktail-Recipe-A-Manhattan/image-import.jpg',  E'{"name": "Big Apple Cocktail Recipe, A Manhattan | Tasting Table", "@type": "Recipe", "image": "https://www.tastingtable.com/img/gallery/Big-Apple-Cocktail-Recipe-A-Manhattan/image-import.jpg", "author": [{"url": "https://www.tastingtable.com/author/tastingtable/", "name": "Tasting Table Staff", "@type": "Person"}], "@context": "https://schema.org", "cookTime": "PT2H", "keywords": "rye whiskey, apple brandy, decanter bitters, apple bitters, luxardo maraschino liqueur, ", "totalTime": "PT2H", "description": "Make this Big Apple cocktail from Marshall Altier at Jbird in New York City.", "recipeYield": [1, "1 cocktail"], "datePublished": "2012-05-18T02:15:00+00:00", "recipeIngredient": ["\\u201cApple\\u201d cherries", "2 ounces apple juice", "2 ounces Pommeau de Normandie", "2 ounces Carpano Antica Formula Vermouth", "2 ounces fresh lemon juice", "2 dashes Luxardo Maraschino liqueur", "4 sheets bloomed gelatin (leaf gelatin softened in cold water for 5 time)", "Canola oil", "Ice", "1\\u00bd ounces high-proof rye whiskey (such as Rittenhouse bonded)", "\\u00bd ounce high-proof apple brandy (such as Laird''s bonded)", "1 ounce Carpano Antica Formula Vermouth", "1 dash The Bitter Truth Jerry Thomas'' Own Decanter Bitters", "2 dashes Bar Keep Baked Apple bitters", "1 \\u201capple\\u201d cherry"], "recipeInstructions": [{"text": "Make the \\"apple\\" cherries: In a saucepan set over medium heat, combine the apple juice, Pommeau de Normandie, vermouth, lemon juice, Maraschino liqueur and softened gelatin until the gelatin is dissolved, about 1 minute.Pour the mixture into a squeeze bottle and cut the tip low enough that a large, cherry-size drop emerges when the bottle is squeezed. Refrigerate until the texture of the mixture thickens, about 1 hour.", "@type": "HowToStep"}, {"text": "Fill a shallow container with canola oil and put it in the freezer until the oil is almost frozen, about 1 hour. Remove the oil from the freezer and squeeze cherry-size drops of the cold apple syrup into the oil solution. Strain the apple cherries through a fine-mesh sieve (save the oil for another use) and rinse under cold water. Transfer to a shallow bowl and refrigerate until needed.", "@type": "HowToStep"}, {"text": "Make the cocktail: Fill a mixing glass or cocktail shaker with ice. Add the whiskey, apple brandy, vermouth and the bitters. Stir well, then strain into a chilled cocktail glass. Garnish with the apple cherry and serve.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:49:44.240135+00:00'::timestamptz, '2026-04-25 19:25:58.679705+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:48.162176+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (41201, 'https://www.tastingtable.com/687912/bridgetown-stiff-punch-recipe-from-the-bon-vivants/', 'tastingtable', 'Bridgetown Stiff Punch Recipe From The Bon Vivants | Tasting Table', 'Tasting Table Staff', 'https://www.tastingtable.com/img/gallery/Bridgetown-Stiff-Punch-Recipe-From-The-Bon-Vivants/image-import.jpg',  E'{"name": "Bridgetown Stiff Punch Recipe From The Bon Vivants | Tasting Table", "@type": "Recipe", "image": "https://www.tastingtable.com/img/gallery/Bridgetown-Stiff-Punch-Recipe-From-The-Bon-Vivants/image-import.jpg", "author": [{"url": "https://www.tastingtable.com/author/tastingtable/", "name": "Tasting Table Staff", "@type": "Person"}], "@context": "https://schema.org", "cookTime": "PT10M", "keywords": "rum, vermouth, tea", "totalTime": "PT10M", "description": "Bridgetown Punch", "recipeYield": [1, "1 batch"], "datePublished": "2012-10-26T23:17:00+00:00", "recipeIngredient": ["1,000 milliliters (4\\u00bc cups) DonQ A\\u00f1ejo Rum", "500 milliliters (2 cups) Noilly Prat Sweet Vermouth", "125 milliliters (\\u00bd cup) B\\u00e9n\\u00e9dictine", "250 milliliter (1 cup) organic apple juice", "250 milliliters (1 cup) unsweetened cranberry juice", "750 milliliters (3\\u00bc cup) rooibos tea, cooled", "125 milliliters (\\u00bd cup) molasses\\u00a0", "250 milliliters (1 cup) fresh lemon juice", "Angostura bitters, to taste", "2 lemons, sliced into wheels, for garnish", "2 apples, sliced thinly, for garnish", "Ice"], "recipeInstructions": [{"text": "In a trash can lined with a plastic bag, combine the rum, vermouth, B\\u00e9n\\u00e9dictine, apple juice, cranberry juice, tea, molasses and lemon juice. Mix well. Add the bitters, to taste. Add the lemon and apple slices. To serve, fill small cups with ice, then ladle the desired serving of punch into each cup.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:49:56.630848+00:00'::timestamptz, '2026-04-25 19:25:59.324463+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:48.728621+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (41387, 'https://www.foodnetwork.com/recipes/giada-de-laurentiis/raspberry-bellini-recipe-1941903', 'foodnetwork', 'Raspberry Bellini', 'Giada De Laurentiis', 'https://food.fnr.sndimg.com/content/dam/images/food/fullset/2003/11/18/0/ei1b03_rasberry_bellini.jpg.rend.hgtvcom.1280.1280.suffix/1386863094840.webp',  E'{"url": "https://www.foodnetwork.com/recipes/giada-de-laurentiis/raspberry-bellini-recipe-1941903", "name": "Raspberry Bellini", "@type": "Recipe", "image": [{"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2003/11/18/0/ei1b03_rasberry_bellini.jpg.rend.hgtvcom.1280.1280.suffix/1386863094840.webp", "@type": "ImageObject", "width": "1280", "height": "1280"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2003/11/18/0/ei1b03_rasberry_bellini.jpg.rend.hgtvcom.1280.960.suffix/1386863094840.webp", "@type": "ImageObject", "width": "1280", "height": "960"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2003/11/18/0/ei1b03_rasberry_bellini.jpg.rend.hgtvcom.1280.720.suffix/1386863094840.webp", "@type": "ImageObject", "width": "1280", "height": "720"}], "video": {"name": "Raspberry Bellini", "@type": "VideoObject", "duration": "PT0H3M09S", "contentUrl": "https://www.foodnetwork.com/apps/api/playback?path=/etc/sni-asset/food/videos/9/92/927/9277/92771", "uploadDate": "2022-08-13T00:43:41.027-04:00", "description": "Whip up a smooth Raspberry Bellini with Everyday Italian.", "thumbnailUrl": "https://food.fnr.sndimg.com/content/dam/images/food/video/9/92/927/9277/92771.jpg.rend.hgtvcom.406.305.suffix/1664906762986.webp"}, "author": [{"url": "https://www.foodnetwork.com/profiles/talent/giada-de-laurentiis", "name": "Giada De Laurentiis", "@type": "Person"}], "review": [{"@type": "Review", "author": {"name": "renee414", "@type": "Person"}, "reviewBody": "Came out nice, pretty color, but not sweet enough for me or my husband and I used an extra tbsp. of sugar. I am also not a big fan of \\"bubbly\\", but thought I would give this a try. Won''t make this again, but I will try the same thing using my favorite wine next time.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 2, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Erin C.", "@type": "Person"}, "reviewBody": "I entertained a group last night and didn''t find this drink to be too tasty.  It''s difficult to get the seeds out of the raspberry mix.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 2, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Donella K.", "@type": "Person"}, "reviewBody": "The recipe as is was ok. My personal taste was to make it a little sweeter and more raspberry flavored. If you like brut, then your good to go.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 3, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "wendy w.", "@type": "Person"}, "reviewBody": "i thought the berries ruined the taste of the champagne. maybe try fresh berries, not frozen", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 2, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Lorna J.", "@type": "Person"}, "reviewBody": "Very refreshing and easy to do.  My friends loved it as did I!", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "ROBIN A.", "@type": "Person"}, "reviewBody": "I don''t know why anyone would give these a high rating...they were terrible! We actually poured them down the drain. What a waste of good champagne and organic raspberries. I''ll stick with good quality juices when making bellinis.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 1, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Melissa S.", "@type": "Person"}, "reviewBody": "Champagne and raspberries how could you go wrong?  This is a nice brunch or summer drink.  Yummy!", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "TERRI C.", "@type": "Person"}, "reviewBody": "I made these at our New Years Eve party.  I followed the directions and they were wonderful.  I ran out before everybody got to try a glass.  Light and refreshing.  Definitly will have at every new years bash and in between.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "TINKER B.", "@type": "Person"}, "reviewBody": "Raspberries and sparkling wine???  YUM", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 4, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "ERNESTO M.", "@type": "Person"}, "reviewBody": "I never tried before this until I saw it on tv. I tried the same very day and I like it so bad, that I am going to make it my favorite", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "TAMI P.", "@type": "Person"}, "reviewBody": "On Thanksgiving I made these for my friends and everyone loved them. I had to quick chill more champagne to supply the demand. Blackberries were freshest in the market so we used those instead. Thank you.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "TERI B.", "@type": "Person"}, "reviewBody": "I loved this...and it''s also great on vanilla ice cream!", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}], "@context": "http://schema.org", "headline": "Raspberry Bellini", "keywords": "Sparkling Wine Recipes,Raspberry Recipes,Pureeing Recipes,Recipes for Parties,Low Sodium,Low-Fat,Italian,Gluten Free,Cocktail Party", "prepTime": "P0Y0M0DT0H10M0.000S", "nutrition": {"@type": "NutritionInformation", "calories": "118", "fatContent": "0g", "servingSize": "1 of 6 servings", "fiberContent": "0g", "sugarContent": "5g", "sodiumContent": "6mg", "proteinContent": "0g", "cholesterolContent": "0mg", "carbohydrateContent": "7g", "saturatedFatContent": "0g"}, "publisher": {"url": "https://www.foodnetwork.com", "logo": {"url": "https://food.fnr.sndimg.com/etc/clientlibs/assets/images/food/fn-logo-flat-60x60.png", "@type": "ImageObject", "width": "60", "height": "60"}, "name": "Food Network", "@type": "Organization"}, "totalTime": "P0Y0M0DT0H10M0.000S", "recipeYield": "6 servings", "dateModified": "2015-04-15T11:00:34.493-04:00", "datePublished": "2015-05-20T11:07:49.791-04:00", "recipeCuisine": "italian", "recipeCategory": "beverage", "aggregateRating": {"@type": "AggregateRating", "ratingValue": 3.7, "reviewCount": 12}, "mainEntityOfPage": true, "recipeIngredient": ["1 bag frozen unsweetened raspberries, thawed", "2 tablespoons sugar", "1 bottle (750-ml) chilled brut Champagne"], "recipeInstructions": [{"text": "Blend the raspberries and sugar in a food processor or blender until pureed. Strain the raspberry puree through a sieve; discard the seeds, if you wish. Set up 6 Champagne flutes and put about 1 tablespoon of raspberry puree in each glass. Add Champagne to each glass; stir gently and serve.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:53:19.379574+00:00'::timestamptz, '2026-04-25 19:26:04.077242+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:17:33.090811+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (41610, 'https://www.foodnetwork.com/recipes/coconut-shellfish-cocktail-recipe-2103940', 'foodnetwork', 'Coconut Shellfish Cocktail', 'Food Network', 'https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.1280.suffix/1474463768097.webp',  E'{"url": "https://www.foodnetwork.com/recipes/coconut-shellfish-cocktail-recipe-2103940", "name": "Coconut Shellfish Cocktail", "@type": "Recipe", "image": [{"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.1280.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "1280"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.960.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "960"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.720.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "720"}], "author": {"name": "Food Network", "@type": "Person"}, "@context": "http://schema.org", "cookTime": "P0Y0M0DT0H40M0.000S", "headline": "Coconut Shellfish Cocktail", "keywords": "Shrimp,Shrimp Cocktail,Shellfish Recipes,Mussel,Scallop Recipes,Main Dish,Lobster,Celery,Coconut Recipes,Coconut Shrimp,Fruit,Appetizer", "prepTime": "P0Y0M0DT0H45M0.000S", "publisher": {"url": "https://www.foodnetwork.com", "logo": {"url": "https://food.fnr.sndimg.com/etc/clientlibs/assets/images/food/fn-logo-flat-60x60.png", "@type": "ImageObject", "width": "60", "height": "60"}, "name": "Food Network", "@type": "Organization"}, "totalTime": "P0Y0M0DT1H25M0.000S", "recipeYield": "6 servings", "dateModified": "2014-01-02T18:38:51.854-05:00", "datePublished": "2016-11-18T16:16:08.108-05:00", "recipeCategory": "appetizer", "mainEntityOfPage": true, "recipeIngredient": ["2 quarts water", "1 cup dry white wine", "1 medium onion, peeled and sliced", "3 celery stalks, chopped", "2 sprigs fresh thyme", "2 sprigs fresh parsley", "1 bay leaf", "1 serrano pepper", "2 allspice berries", "4 black peppercorns", "1 (14-ounce) can coconut milk (can use fresh coconut milk, if desired)", "1/2 cup fresh lime juice", "1 poblano pepper, cut into brunoise", "2 serrano peppers, finely chopped", "1 red bell pepper, julienned", "1 red onion, julienned", "1 tablespoon minced garlic", "1 teaspoon peeled and minced fresh ginger", "1/4 cup chopped scallions", "1 tablespoon chopped fresh cilantro leaves", "Salt and pepper", "16 to 20 shrimp, shell on", "24 crayfish", "8 scallops", "1 (8-ounce) lobster tail", "24 mussels, scrubbed and debearded", "1 conch, meat cut into small dice", "3 whole coconuts, shells cut in half and milk drained, for serving", "Shaved fresh coconut, for garnish", "Fresh cilantro leaves, for garnish"], "recipeInstructions": [{"text": "For the court bouillon: Place all ingredients in a large pot. Bring to a boil and then reduce the heat and simmer for 20 minutes.\\u00a0", "@type": "HowToStep"}, {"text": "For the marinade: Mix all ingredients together in a large non-reactive baking dish or large shallow bowl. Season, to taste, with salt and pepper.\\u00a0", "@type": "HowToStep"}, {"text": "For the shellfish: Add salt, to taste, to the simmering court bouillon. Add the shrimp, crayfish, and scallops to the court bouillon and cook all together for 3 minutes. Remove fish from court bouillon and cool before peeling. Transfer to marinade.\\u00a0", "@type": "HowToStep"}, {"text": "Add lobster to simmering court bouillon and cook for 5 minutes. Remove meat from shell, cut into about 12 chunks, and add to marinade.\\u00a0", "@type": "HowToStep"}, {"text": "Add mussels to simmering court bouillon and cook until they have opened. Discard any mussels that did not open. Remove meat from shell on all but 6 mussels and add to marinade; save 6 whole mussels for garnish.\\u00a0", "@type": "HowToStep"}, {"text": "Add conch to simmering court bouillon and cook for 30 seconds. Transfer to marinade and toss gently to evenly combine all the seafood.\\u00a0", "@type": "HowToStep"}, {"text": "Fill a 2-inch round mold with seafood cocktail mixture. Transfer to a coconut shell for serving. Repeat to make 6 servings. Pour extra marinade over top and garnish each with 1 reserved mussel in shell, shaved fresh coconut, and cilantro.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:54:58.379925+00:00'::timestamptz, '2026-04-25 19:26:15.509022+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:50.806838+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (41615, 'https://www.foodnetwork.com/recipes/coquito-coconut-rum-eggnog-recipe-1926522', 'foodnetwork', 'Coquito (Coconut Rum Eggnog)', 'Food Network', 'https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.1280.suffix/1474463768097.webp',  E'{"url": "https://www.foodnetwork.com/recipes/coquito-coconut-rum-eggnog-recipe-1926522", "name": "Coquito (Coconut Rum Eggnog)", "@type": "Recipe", "image": [{"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.1280.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "1280"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.960.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "960"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.720.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "720"}], "author": {"name": "Food Network", "@type": "Person"}, "review": [{"@type": "Review", "author": {"name": "Carol M.", "@type": "Person"}, "reviewBody": "G", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 1, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Jose C.", "@type": "Person"}, "reviewBody": "This is a GREAT and easy alternative to the traditional Puertorican recipe. I\\u2019ve been using it for the past 4 yrs. and I\\u2019ve always gotten excellent comments. ", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "AIDA A.", "@type": "Person"}, "reviewBody": "VERY GOOD.  ONE COMMENT SAID THEY ADD RAISINS TO THE COQUITO????? I NEVER HEARD SUCH A THING..........................", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 3, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Cynthia C.", "@type": "Person"}, "reviewBody": "I come from a big Puerto Rican family and our coquito during the Christmas season is a must! This coquito is delicious. My family loves it, and I''m asked to make this coquito recipe every year!! Great recipe! ", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Dennis M.", "@type": "Person"}, "reviewBody": "First of all, if coconut milk is used, it will waste the recipe. Coconut cream is what it is used for coquito. The procedure is not accurate also. Here is the real recipe: \\r<br />\\r<br />Coquito \\r<br /> \\r<br />Ingredients:\\r<br />?\\t1/2 L Water \\r<br />?\\t15 oz Cream of coconut \\r<br />?\\t12 oz evaporated Milk \\r<br />?\\t14 oz Condensed milk \\r<br />?\\t4 Egg yolk \\r<br />?\\t2-3 sticks Cinnamon \\r<br />?\\t1 L White rum \\r<br />Mixing instructions:\\r<br />Boil the cinnamon sticks in the water. Take the sticks out when the water is yellow and has the smell and taste of cinnamon. Add the evaporated milk, condensed milk and egg yolks and cook at low temperature. While it''s cooking stir to avoid it sticking to the bottom of the pot. When it is boiling for a few minutes, add the cream of coconut and rum. Stir well and take off the burner. Let it cool and it will be ready. Keep it in the refrigerator and it will last for a very long time.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 2, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Miriam V.", "@type": "Person"}, "reviewBody": "It was very good. And for the previous posting this drink is not suppose to taste like eggs. It is a coconut nog.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}], "@context": "http://schema.org", "headline": "Coquito (Coconut Rum Eggnog)", "keywords": "Rum Recipes,Pureeing Recipes,Mixed Drink Recipes,Low Sodium,Eggnog,Liquor Recipes,Easy Dessert Recipes,Dessert,Gluten Free,Coconut Recipes,Fruit,Fruit Dessert Recipes,Brandy", "nutrition": {"@type": "NutritionInformation", "calories": "332", "fatContent": "15g", "servingSize": "1 of 20 servings", "fiberContent": "0g", "sugarContent": "20g", "sodiumContent": "102mg", "proteinContent": "7g", "cholesterolContent": "69mg", "carbohydrateContent": "21g", "saturatedFatContent": "11g"}, "publisher": {"url": "https://www.foodnetwork.com", "logo": {"url": "https://food.fnr.sndimg.com/etc/clientlibs/assets/images/food/fn-logo-flat-60x60.png", "@type": "ImageObject", "width": "60", "height": "60"}, "name": "Food Network", "@type": "Organization"}, "dateModified": "2013-11-14T18:40:00.537-05:00", "datePublished": "2015-05-09T06:43:49.173-04:00", "recipeCategory": "dessert", "aggregateRating": {"@type": "AggregateRating", "ratingValue": 3.9, "reviewCount": 8}, "mainEntityOfPage": true, "recipeIngredient": ["6 eggs", "3/4 (750 ml) bottle white rum", "2 (14 ounce) cans coconut milk", "2 (14 ounce) cans evaporated milk", "2 (10 ounce) cans sweetened condensed milk", "2 tablespoons vanilla", "1 cup brandy"], "recipeInstructions": [{"text": "In a blender, beat the eggs and the rum at high speed. Lower blender setting and add all additional ingredients. Bottle and chill well. Serve in small liqueur, glasses.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:55:06.263903+00:00'::timestamptz, '2026-04-25 19:26:15.695067+00:00'::timestamptz, 'Coquito', 'alias', 'v1', '2026-05-03 23:16:50.806838+00:00'::timestamptz, NULL, '70c7b6c01693d632972b40c75a9e2a27cd86eb687782117544ed9b1d8b50b9cd', 'v1');
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (42073, 'https://www.foodnetwork.com/recipes/alpine-martini-recipe-1947066', 'foodnetwork', 'Alpine Martini', 'Food Network', 'https://food.fnr.sndimg.com/content/dam/images/food/fullset/2007/1/12/1/wg0101_martini2.jpg.rend.hgtvcom.1280.1280.suffix/1385127552428.webp',  E'{"url": "https://www.foodnetwork.com/recipes/alpine-martini-recipe-1947066", "name": "Alpine Martini", "@type": "Recipe", "image": [{"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2007/1/12/1/wg0101_martini2.jpg.rend.hgtvcom.1280.1280.suffix/1385127552428.webp", "@type": "ImageObject", "width": "1280", "height": "1280"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2007/1/12/1/wg0101_martini2.jpg.rend.hgtvcom.1280.960.suffix/1385127552428.webp", "@type": "ImageObject", "width": "1280", "height": "960"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2007/1/12/1/wg0101_martini2.jpg.rend.hgtvcom.1280.720.suffix/1385127552428.webp", "@type": "ImageObject", "width": "1280", "height": "720"}], "author": {"name": "Food Network", "@type": "Person"}, "review": [{"@type": "Review", "author": {"name": "Sean W.", "@type": "Person"}, "reviewBody": "Loved it, the only change I would make is adding a second scoop of sorbet for a 6oz martini glass. Break up the first scoop and use the second as the garnish with the cedar frond along with 4oz vodka.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 4, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Connie L.", "@type": "Person"}, "reviewBody": "Drink is wonderful......sorry to hear the restaurant is closing :-(", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Mr. E", "@type": "Person"}, "reviewBody": "I was so happy to catch Giada?s Seattle weekend getaway episode just before I went there for my birthday. After watching the episode, it gave me the inspiration to go to some of these places to celebrate my birthday: Cascadia for pre-celebration drinks, the Dahlia Lounge for dinner and dessert, and Victrola for a late coffee and extra dessert. (Hey, it was my birthday, so I could have an extra dessert!) While at Cascadia I of course had to have the Alpine Martini and I was totally impressed with it. I was even lucky enough to have the same bartender who made Giada?s drink on the episode make mine. How cool is that? Knowing how it should taste (nothing like watching the master first make it to give you base guide), I couldn?t wait to make this drink for myself. Before I left Seattle, I collected a small bunch of Douglas Fir leaves (what better place to get them than from the Pacific Northwest?) and brought them home to make the sorbet. This is one delicious drink that I love making. Next time I?m in Seattle I?ll bring home more Douglas Fir leaves and I?ll also make it a point to stop back into Cascadia for a ?brusher-upper? martini lesson or two and also try their mini-burgers; I saw them while I was there and boy they look even better in person than they did on the episode. BTW, after I left Cascadia, I went to the Dahlia Lounge for dinner and dessert. I had the exact same things Giada did; the salad was wonderful, the crab cakes were out of this world and the donuts were to die for. Best of all, since it was my birthday, the donuts were free, courtesy of the Dahlia Lounge. Thanks to my partner, to the staff at Cascadia, the Dahlia Lounge and Victrola, and to Giada for helping make my birthday a memorable one. Grazie per tutti Giada!", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "lynn s.", "@type": "Person"}, "reviewBody": "Fabulous!! Not hard to make (snipped some pine off my Douglas Fir Christmas Tree for the sorbet!)It is very \\"cool\\" to look at too. Thoroughly enjoyed it! Rivals my favorite LemonDrop Martini made with Limoncello.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}], "@context": "http://schema.org", "cookTime": "P0Y0M0DT0H10M0.000S", "headline": "Alpine Martini", "keywords": "Vodka Recipes,Sorbet Recipes,Mixed Drink Recipes,Sugar,Liquor Recipes,Ice Cream,Gin Recipes,Martini", "prepTime": "P0Y0M0DT0H15M0.000S", "publisher": {"url": "https://www.foodnetwork.com", "logo": {"url": "https://food.fnr.sndimg.com/etc/clientlibs/assets/images/food/fn-logo-flat-60x60.png", "@type": "ImageObject", "width": "60", "height": "60"}, "name": "Food Network", "@type": "Organization"}, "totalTime": "P0Y0M0DT0H25M0.000S", "recipeYield": "1 serving", "dateModified": "2013-11-08T12:41:15.618-05:00", "datePublished": "2016-11-18T15:54:57.937-05:00", "recipeCategory": "beverage", "aggregateRating": {"@type": "AggregateRating", "ratingValue": 4.8, "reviewCount": 4}, "mainEntityOfPage": true, "recipeIngredient": ["1 1/2 ounces citron vodka", "1 (#40) ice cream scoop Douglas Fir Sorbet, recipe follows", "1 cup water", "1 cup sugar", "8 inches Douglas fir (cut into 1-inch lengths)", "1 tablespoon gin"], "recipeInstructions": [{"text": "1 small cedar frond, garnish", "@type": "HowToStep"}, {"text": "Chill a cocktail glass. Place vodka in a cocktail shaker with ice and shake vigorously. Place a perfectly round scoop of Douglas Fir Sorbet in the bottom of the glass. Stick cedar frond into scoop of sorbet. Pour chilled vodka over the top. Sorbet should float.", "@type": "HowToStep"}, {"text": "Boil first cup of water with sugar and Douglas fir for 10 minutes. Strain and cool.", "@type": "HowToStep"}, {"text": "Add second cup of water and gin.", "@type": "HowToStep"}, {"text": "Churn as directed on your ice cream machine. Garnish with a sprig of Douglas fir.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 20:59:01.477110+00:00'::timestamptz, '2026-04-25 19:26:34.576516+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:46.412664+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (42250, 'https://www.foodnetwork.com/recipes/bobby-flay/cranberry-orange-cinnamon-vodka-tonic-2369129', 'foodnetwork', 'Cranberry-Orange-Cinnamon Vodka Tonic', 'Bobby Flay', 'https://food.fnr.sndimg.com/content/dam/images/food/fullset/2014/2/10/0/CCBAB412-Cranberry-Orange-Vodka-Tonic-Recipe_s4x3.jpg.rend.hgtvcom.1280.1280.suffix/1396271488816.webp',  E'{"url": "https://www.foodnetwork.com/recipes/bobby-flay/cranberry-orange-cinnamon-vodka-tonic-2369129", "name": "Cranberry-Orange-Cinnamon Vodka Tonic", "@type": "Recipe", "image": [{"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2014/2/10/0/CCBAB412-Cranberry-Orange-Vodka-Tonic-Recipe_s4x3.jpg.rend.hgtvcom.1280.1280.suffix/1396271488816.webp", "@type": "ImageObject", "width": "1280", "height": "1280"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2014/2/10/0/CCBAB412-Cranberry-Orange-Vodka-Tonic-Recipe_s4x3.jpg.rend.hgtvcom.1280.960.suffix/1396271488816.webp", "@type": "ImageObject", "width": "1280", "height": "960"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2014/2/10/0/CCBAB412-Cranberry-Orange-Vodka-Tonic-Recipe_s4x3.jpg.rend.hgtvcom.1280.720.suffix/1396271488816.webp", "@type": "ImageObject", "width": "1280", "height": "720"}], "author": [{"url": "https://www.foodnetwork.com/profiles/talent/bobby-flay", "name": "Bobby Flay", "@type": "Person"}], "@context": "http://schema.org", "cookTime": "P0Y0M0DT0H10M0.000S", "headline": "Cranberry-Orange-Cinnamon Vodka Tonic", "keywords": "Vodka Recipes,Orange Recipes,Mixed Drink Recipes,Low Sodium,Low-Fat,Cranberry,Gluten Free,Brunch", "nutrition": {"@type": "NutritionInformation", "calories": "914", "fatContent": "0g", "servingSize": "1 of 1 servings", "fiberContent": "1g", "sugarContent": "205g", "sodiumContent": "4mg", "proteinContent": "0g", "cholesterolContent": "0mg", "carbohydrateContent": "208g", "saturatedFatContent": "0g"}, "publisher": {"url": "https://www.foodnetwork.com", "logo": {"url": "https://food.fnr.sndimg.com/etc/clientlibs/assets/images/food/fn-logo-flat-60x60.png", "@type": "ImageObject", "width": "60", "height": "60"}, "name": "Food Network", "@type": "Organization"}, "totalTime": "P0Y0M0DT0H25M0.000S", "recipeYield": "1 serving", "dateModified": "2015-12-15T16:21:14.934-05:00", "datePublished": "2017-01-04T12:55:42.356-05:00", "recipeCategory": "beverage", "mainEntityOfPage": true, "recipeIngredient": ["1 cup granulated sugar", "6 fresh or frozen and thawed cranberries\\u00a0", "One 2-inch strip orange peel\\u00a0", "2 tablespoons freshly squeezed orange juice\\u00a0", "1 shot (1 1/2 ounces) best quality cinnamon vodka", "1 teaspoon orange liquor, such as Triple Sec\\u00a0", "Plain, cranberry or orange flavored tonic water\\u00a0"], "recipeInstructions": [{"text": "For the simple syrup: Bring the sugar and 1 cup water to a boil in a small saucepan. When the sugar is completely dissolved, remove the saucepan from the heat and cool the syrup to room temperature.", "@type": "HowToStep"}, {"text": "For the vodka tonic: Muddle the cranberries, orange peel and 1 to 2 tablespoons simple syrup (depending on how sweet you like your drink) in a rocks glass. Add the orange juice, vodka and orange liquor, fill 3/4 of way with the tonic and add ice cubes. Serve immediately. Reserve the remaining simple syrup for another use. It will keep in the refrigerator, covered, for up to 1 month.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:00:32.254280+00:00'::timestamptz, '2026-04-25 19:26:41.483977+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:51.938866+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (42483, 'https://www.foodnetwork.com/recipes/amy-thielen/birch-whiskey-snow-cocktail-2355821', 'foodnetwork', 'Birch Whiskey Snow Cocktail', 'Amy Thielen', 'https://food.fnr.sndimg.com/content/dam/images/food/video/0/02/022/0221/0221730.jpg.rend.hgtvcom.1280.1280.suffix/1661176182206.webp',  E'{"url": "https://www.foodnetwork.com/recipes/amy-thielen/birch-whiskey-snow-cocktail-2355821", "name": "Birch Whiskey Snow Cocktail", "@type": "Recipe", "image": [{"url": "https://food.fnr.sndimg.com/content/dam/images/food/video/0/02/022/0221/0221730.jpg.rend.hgtvcom.1280.1280.suffix/1661176182206.webp", "@type": "ImageObject", "width": "1280", "height": "1280", "description": "This image has been migrated from FGS and has been distributed to our partners."}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/video/0/02/022/0221/0221730.jpg.rend.hgtvcom.1280.960.suffix/1661176182206.webp", "@type": "ImageObject", "width": "1280", "height": "960", "description": "This image has been migrated from FGS and has been distributed to our partners."}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/video/0/02/022/0221/0221730.jpg.rend.hgtvcom.1280.720.suffix/1661176182206.webp", "@type": "ImageObject", "width": "1280", "height": "720", "description": "This image has been migrated from FGS and has been distributed to our partners."}], "video": {"name": "Birch Whiskey Snow Cocktail", "@type": "VideoObject", "duration": "PT0H1M36S", "contentUrl": "https://www.foodnetwork.com/apps/api/playback?path=/etc/sni-asset/food/videos/0/02/022/0221/0221730", "uploadDate": "2022-08-22T10:05:47.417-04:00", "description": "Amy''s Birch Whiskey Snow Cocktail is an adult treat made with real snow.", "thumbnailUrl": "https://food.fnr.sndimg.com/content/dam/images/food/video/0/02/022/0221/0221730.jpg.rend.hgtvcom.406.305.suffix/1661176182206.webp"}, "author": [{"url": "https://www.foodnetwork.com/profiles/talent/amy-thielen", "name": "Amy Thielen", "@type": "Person"}], "review": [{"@type": "Review", "author": {"name": "gourmet bachelor", "@type": "Person"}, "reviewBody": "Reminds me of the mountains", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "jschultz6", "@type": "Person"}, "reviewBody": "I loved it!  We made ours with Kentucky Bourbon and local maple syrup--don''t forget the maple lacquered bacon to go with it (that just made the drink IMO.)  Perfect sipping drink for those days when Winter doesn''t want to let go and Spring is trying to slip in.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 4, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "ken p.", "@type": "Person"}, "reviewBody": "not good at all", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 1, "worstRating": "1"}}], "@context": "http://schema.org", "cookTime": "P0Y0M0DT0H10M0.000S", "headline": "Birch Whiskey Snow Cocktail", "keywords": "Whiskey Recipes,Mixed Drink Recipes,Bourbon", "publisher": {"url": "https://www.foodnetwork.com", "logo": {"url": "https://food.fnr.sndimg.com/etc/clientlibs/assets/images/food/fn-logo-flat-60x60.png", "@type": "ImageObject", "width": "60", "height": "60"}, "name": "Food Network", "@type": "Organization"}, "totalTime": "P0Y0M0DT0H40M0.000S", "recipeYield": "6 to 8 servings", "dateModified": "2014-06-04T10:33:15.209-04:00", "datePublished": "2015-08-11T09:23:30.016-04:00", "aggregateRating": {"@type": "AggregateRating", "ratingValue": 3.3, "reviewCount": 3}, "mainEntityOfPage": true, "recipeIngredient": ["6 ounces (3/4 cup) bourbon or your whiskey of choice", "4 ounces (1/2 cup) birch syrup or maple syrup\\u00a0", "2 ounces (1/4 cup) dry sherry\\u00a0", "2 drops bitters if using maple syrup\\u00a0", "Freshly fallen snow or shaved ice\\u00a0"], "recipeInstructions": [{"text": "In a pitcher, mix together the whiskey, syrup, sherry, and bitters if using. Chill thoroughly.", "@type": "HowToStep"}, {"text": "Before serving, fill small highball glasses (or half-pint jelly jars) with snow, packing it down lightly. Drizzle in the cold whiskey mixture, adding as much or as little as desired. Serve with a small spoon.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:02:08.674283+00:00'::timestamptz, '2026-04-25 19:26:51.219228+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:48.162176+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (42552, 'https://www.foodnetwork.com/recipes/ina-garten/cranberry-martinis-9564294', 'foodnetwork', 'Cranberry Martinis', 'Ina Garten', 'https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.1280.suffix/1474463768097.webp',  E'{"url": "https://www.foodnetwork.com/recipes/ina-garten/cranberry-martinis-9564294", "name": "Cranberry Martinis", "@type": "Recipe", "image": [{"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.1280.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "1280"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.960.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "960"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.720.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "720"}], "author": [{"url": "https://www.foodnetwork.com/profiles/talent/ina-garten", "name": "Ina Garten", "@type": "Person"}], "review": [{"@type": "Review", "author": {"name": "Kara E.", "@type": "Person"}, "reviewBody": "Literally Ina, you and I need to hang with the grey goose. We can be friends. Sooo this cocktail is not for the \\"cheap date\\". Be very careful,  you will not be able to drive after 1. ", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "cakeman67", "@type": "Person"}, "reviewBody": "So easy to make and way too easy to enjoy.  I\\u2019m not a sweet martini guy and found this recipe, as written, to be perfect. I agree that the pitcher keeps well in the fridge.  I may try freezing the mix for future enjoyment. ", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "mbpaul", "@type": "Person"}, "reviewBody": "I\\u2019ve made these for three years or so - thanks to aIna\\u2019s cookbook recipe.  Winner! Not too sweet (alter the amount of triple sec if you want); refreshing and waaay easy to sip on.  Guests always rave...and the pitcher will stay drinkable in the fridge for days ", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}], "@context": "http://schema.org", "cookTime": "P0Y0M0DT0H15M0.000S", "headline": "Cranberry Martinis", "keywords": "Cranberry,Martini", "publisher": {"url": "https://www.foodnetwork.com", "logo": {"url": "https://food.fnr.sndimg.com/etc/clientlibs/assets/images/food/fn-logo-flat-60x60.png", "@type": "ImageObject", "width": "60", "height": "60"}, "name": "Food Network", "@type": "Organization"}, "totalTime": "P0Y0M2DT0H15M0.000S", "recipeYield": "6 servings", "dateModified": "2020-12-02T14:00:30.806-05:00", "datePublished": "2020-12-02T14:00:32.399-05:00", "recipeCategory": "beverage", "aggregateRating": {"@type": "AggregateRating", "ratingValue": 5, "reviewCount": 5}, "mainEntityOfPage": true, "recipeIngredient": ["1 cup sugar", "1 cup fresh cranberries\\u00a0", "6 (1-by-3-inch) strips of orange zest, plus extra for serving (see Cook''s Note)\\u00a0", "1 (750 milliliter) bottle good vodka, such as Grey Goose\\u00a0", "1 cup cranberry juice cocktail, preferably tart\\u00a0", "1/4 cup Triple Sec\\u00a0", "Ice"], "recipeInstructions": [{"text": "Several days ahead, place the sugar, cranberries, 6 strips of orange zest, and 1 cup of water in a small saucepan. Bring to a boil, lower the heat, and simmer for 5 minutes, until the cranberries start to pop open. Pour the vodka into a large pitcher, add the cranberry mixture, and store covered in the refrigerator for at least 2 days and up to 5 days.", "@type": "HowToStep"}, {"text": "When ready to serve, strain the vodka mixture, reserving the cranberries and discarding the orange zest. Stir in the cranberry juice cocktail and Triple Sec. Fill a cocktail shaker with ice, add the drink mixture, shake for a full 30 seconds (it''s longer than you think!), and strain into martini glasses. Rub the rim of each glass with fresh orange zest, spoon a few cranberries into each glass, and serve ice cold.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:02:38.295125+00:00'::timestamptz, '2026-04-25 19:26:54.295305+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:51.938866+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (42684, 'https://www.foodnetwork.com/recipes/sandra-lee/pineapple-limeade-recipe2-1918600', 'foodnetwork', 'Pineapple Limeade', 'Sandra Lee', 'https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.1280.suffix/1474463768097.webp', '{"url": "https://www.foodnetwork.com/recipes/sandra-lee/pineapple-limeade-recipe2-1918600", "name": "Pineapple Limeade", "@type": "Recipe", "image": [{"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.1280.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "1280"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.960.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "960"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.720.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "720"}], "author": [{"url": "https://www.foodnetwork.com/profiles/talent/sandra-lee", "name": "Sandra Lee", "@type": "Person"}], "review": [{"@type": "Review", "author": {"name": "Food Network User", "@type": "Person"}, "reviewBody": "awesome, and it was so simple.it took about 5 minutes even though it says 10.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Nadia O.", "@type": "Person"}, "reviewBody": "delicious!", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "JJRivard", "@type": "Person"}, "reviewBody": "This drink is great. It is so refreshing. I made 1/2 the  recipe to see if we would like it. I promptly doubled the recipe for the company we were having that evening. They all loved it. ", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Sara D.", "@type": "Person"}, "reviewBody": "I took this to a friend''s house last night and everyone loved it. Think of it more as a pineapple margarita. Also used fizzy water rather than tap. Thanks for this one Sandra!", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}], "@context": "http://schema.org", "headline": "Pineapple Limeade", "keywords": "Pineapples,Lime Recipes", "prepTime": "P0Y0M0DT0H10M0.000S", "publisher": {"url": "https://www.foodnetwork.com", "logo": {"url": "https://food.fnr.sndimg.com/etc/clientlibs/assets/images/food/fn-logo-flat-60x60.png", "@type": "ImageObject", "width": "60", "height": "60"}, "name": "Food Network", "@type": "Organization"}, "totalTime": "P0Y0M0DT0H10M0.000S", "recipeYield": "4 servings", "dateModified": "2014-01-09T01:54:19.971-05:00", "datePublished": "2016-11-20T23:58:26.106-05:00", "recipeCategory": "beverage", "aggregateRating": {"@type": "AggregateRating", "ratingValue": 4.6, "reviewCount": 5}, "mainEntityOfPage": true, "recipeIngredient": ["4 limes", "1 (20-ounce) can pineapple slices", "Reserved pineapple juice from Chicken Burritos with Pineapple Salsa recipe", "1/4 cup sugar", "1 cup water", "4 ounces tequila, optional"], "recipeInstructions": [{"text": "Cut the limes into small pieces and reserve 4 slices for garnish. Strain the juice from the pineapple slices and combine with the reserved pineapple juice. Set aside 4 pineapple slices for garnish and roughly chop the remainder.", "@type": "HowToStep"}, {"text": "In a pitcher muddle the limes and stir in the sugar. Add the chopped pineapple, and muddle a bit more. Stir in the pineapple juice and 1 cup water. Add tequila, if desired.", "@type": "HowToStep"}, {"text": "Serve in ice filled glasses garnished with pineapple and lime slices.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:03:30.654130+00:00'::timestamptz, '2026-04-25 19:26:59.307608+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:17:25.187973+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (42740, 'https://www.foodnetwork.com/recipes/sandra-lee/dollar-martini-recipe-1941115', 'foodnetwork', 'Dollar Martini', 'Sandra Lee', 'https://food.fnr.sndimg.com/content/dam/images/food/fullset/2008/10/2/0/SH1105_Dollar-Martini.jpg.rend.hgtvcom.1280.1280.suffix/1371587431197.webp', '{"url": "https://www.foodnetwork.com/recipes/sandra-lee/dollar-martini-recipe-1941115", "name": "Dollar Martini", "@type": "Recipe", "image": [{"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2008/10/2/0/SH1105_Dollar-Martini.jpg.rend.hgtvcom.1280.1280.suffix/1371587431197.webp", "@type": "ImageObject", "width": "1280", "height": "1280"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2008/10/2/0/SH1105_Dollar-Martini.jpg.rend.hgtvcom.1280.960.suffix/1371587431197.webp", "@type": "ImageObject", "width": "1280", "height": "960"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2008/10/2/0/SH1105_Dollar-Martini.jpg.rend.hgtvcom.1280.720.suffix/1371587431197.webp", "@type": "ImageObject", "width": "1280", "height": "720"}], "author": [{"url": "https://www.foodnetwork.com/profiles/talent/sandra-lee", "name": "Sandra Lee", "@type": "Person"}], "review": [{"@type": "Review", "author": {"name": "K Y.", "@type": "Person"}, "reviewBody": "It was tasty for a quick recipe.  I made pitchers of this adding Burnett''s Citrus Vodka and it was a hit.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Glutton", "@type": "Person"}, "reviewBody": "Even using cheap vodka would be a waste of coin.  None of my guests liked this drink - it was the limeade.  Either use real limes or lime juice; neither is that expensive.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 2, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Wes H.", "@type": "Person"}, "reviewBody": "This a great simple drink for summer time around the grill and the pool. You dont need to use good vodka, honestly I drink my fair share fo vodka and to mix something such as Grey Goose or Belevedere, etc is just a waste. Also this bascially what my freinds called 50 cent margiritas. Instead of Vodka get out a little Jose and grab the rock salt for the glass. Also Jose make an orange flavored bottle that is a great contrast to the limeade mix", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 4, "worstRating": "1"}}], "@context": "http://schema.org", "headline": "Dollar Martini", "keywords": "Low Sodium,Low-Fat,Lemon,Gluten Free,Martini", "prepTime": "P0Y0M0DT0H3M0.000S", "nutrition": {"@type": "NutritionInformation", "calories": "160", "fatContent": "0g", "servingSize": "1 of 4 servings", "fiberContent": "0g", "sugarContent": "8g", "sodiumContent": "5mg", "proteinContent": "0g", "cholesterolContent": "0mg", "carbohydrateContent": "8g", "saturatedFatContent": "0g"}, "publisher": {"url": "https://www.foodnetwork.com", "logo": {"url": "https://food.fnr.sndimg.com/etc/clientlibs/assets/images/food/fn-logo-flat-60x60.png", "@type": "ImageObject", "width": "60", "height": "60"}, "name": "Food Network", "@type": "Organization"}, "totalTime": "P0Y0M0DT0H3M0.000S", "recipeYield": "4 servings", "dateModified": "2013-11-05T18:50:15.377-05:00", "datePublished": "2016-11-20T23:56:19.665-05:00", "recipeCategory": "beverage", "aggregateRating": {"@type": "AggregateRating", "ratingValue": 3.7, "reviewCount": 3}, "mainEntityOfPage": true, "recipeIngredient": ["1 cup vodka", "1 cup water", "1 (8-ounce) can frozen limeade", "2 tablespoon lemon juice"], "recipeInstructions": [{"text": "In a large pitcher, combine vodka, water, limeade and lemon juice. Pour into martini glasses.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:04:03.382066+00:00'::timestamptz, '2026-04-25 19:27:01.408515+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:16:52.798781+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (42775, 'https://www.foodnetwork.com/recipes/sandra-lee/hula-girl-cocktail-recipe-1952198', 'foodnetwork', 'Hula Girl Cocktail', 'Sandra Lee', 'https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.1280.suffix/1474463768097.webp', '{"url": "https://www.foodnetwork.com/recipes/sandra-lee/hula-girl-cocktail-recipe-1952198", "name": "Hula Girl Cocktail", "@type": "Recipe", "image": [{"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.1280.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "1280"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.960.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "960"}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/editorial/homepage/fn-feature.jpg.rend.hgtvcom.1280.720.suffix/1474463768097.webp", "@type": "ImageObject", "width": "1280", "height": "720"}], "author": [{"url": "https://www.foodnetwork.com/profiles/talent/sandra-lee", "name": "Sandra Lee", "@type": "Person"}], "review": [{"@type": "Review", "author": {"name": "Marielyr", "@type": "Person"}, "reviewBody": "This drink is FANTABULOUS!!!! It was like taking a Vacation. The entire menu that goes along with this drink is also Brilliant. Thank you Sandra!!!", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "sharaz52", "@type": "Person"}, "reviewBody": "delicious", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Jennifer C.", "@type": "Person"}, "reviewBody": "This drink was a hit with the ladies. Delicious!!!!", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Lisa H.", "@type": "Person"}, "reviewBody": "I don''t usually like alcoholic drinks because of the strong taste, but this drink is an exception.  The fruit juices mask the bitter taste of the rum and make it very light and refreshing.  The strawberries make it look like a tropical sunset.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Adrienne S.", "@type": "Person"}, "reviewBody": "For the alcoholic version, I suggest you substitute the new Bacardi Dragonberry Rum- wow! Zing! It has a strawberry kick.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}, {"@type": "Review", "author": {"name": "Lori C.", "@type": "Person"}, "reviewBody": "This is a really fun and refreshing drink. I made one batch with the rum for the adults and one without for the kids. I also made a batch without the guava nectar juice and added 2 cans of orange juice instead, also replaced the straweberries with slices from one orange. It''s a great drink to sit by the pool with and eat those chicken skewers! Yummy! Thanks Sandra! ", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": 5, "worstRating": "1"}}], "@context": "http://schema.org", "headline": "Hula Girl Cocktail", "keywords": "Rum Recipes,Punch Recipes,Pineapples,Low Sodium,Low-Fat,Hawaiian Recipes,Guava Recipes,Gluten Free,Cocktail Party,Recipes for a Crowd,American", "prepTime": "P0Y0M0DT0H3M0.000S", "nutrition": {"@type": "NutritionInformation", "calories": "151", "fatContent": "0g", "servingSize": "1 of 8 servings", "fiberContent": "2g", "sugarContent": "17g", "sodiumContent": "21mg", "proteinContent": "0g", "cholesterolContent": "0mg", "carbohydrateContent": "22g", "saturatedFatContent": "0g"}, "publisher": {"url": "https://www.foodnetwork.com", "logo": {"url": "https://food.fnr.sndimg.com/etc/clientlibs/assets/images/food/fn-logo-flat-60x60.png", "@type": "ImageObject", "width": "60", "height": "60"}, "name": "Food Network", "@type": "Organization"}, "totalTime": "P0Y0M0DT0H3M0.000S", "recipeYield": "8 servings", "dateModified": "2014-06-11T13:44:08.204-04:00", "datePublished": "2016-11-20T23:57:14.346-05:00", "recipeCuisine": "american", "recipeCategory": "beverage", "aggregateRating": {"@type": "AggregateRating", "ratingValue": 5, "reviewCount": 6}, "mainEntityOfPage": true, "recipeIngredient": ["4 cups ice", "2 (6-ounce) cans pineapple juice", "2 (12-ounce) cans guava nectar juice", "1 1/2 cups club soda", "1/2 (16-ounce) bag frozen strawberries", "1 cup white rum (optional)"], "recipeInstructions": [{"text": "Add ice, pineapple juice, guava nectar juice, seltzer water and frozen strawberries to a punch bowl. Mix together and pour into glasses (Add 1 cup of white rum if you want an alcoholic version).", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:04:07.245153+00:00'::timestamptz, '2026-04-25 19:27:02.676292+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:17:01.011669+00:00'::timestamptz, NULL, NULL, NULL);
insert into public.recipes (id, source_url, site, name, author, image_url, jsonld, fetched_at, extracted_at, canonical_name, canonical_name_source, normalizer_version, normalized_at, cluster_id, variant_key, dedup_version) values (42864, 'https://www.foodnetwork.com/recipes/sandra-lee/venice-sunset-cocktail-recipe-1918838', 'foodnetwork', 'Venice Sunset Cocktail', 'Sandra Lee', 'https://food.fnr.sndimg.com/content/dam/images/food/fullset/2010/5/21/0/SM0303_01_venice-sunset-cocktail_s4x3.jpg.rend.hgtvcom.1280.1280.suffix/1371593014431.webp', '{"url": "https://www.foodnetwork.com/recipes/sandra-lee/venice-sunset-cocktail-recipe-1918838", "name": "Venice Sunset Cocktail", "@type": "Recipe", "image": [{"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2010/5/21/0/SM0303_01_venice-sunset-cocktail_s4x3.jpg.rend.hgtvcom.1280.1280.suffix/1371593014431.webp", "@type": "ImageObject", "width": "1280", "height": "1280", "description": "Two champagne glasses that have been filled with ingredients to make a venice sunset cocktail. These were made with a cherry sauce, sparkling white grape juice, and grapefruit juice. Cherries were placed on skewers for garnish."}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2010/5/21/0/SM0303_01_venice-sunset-cocktail_s4x3.jpg.rend.hgtvcom.1280.960.suffix/1371593014431.webp", "@type": "ImageObject", "width": "1280", "height": "960", "description": "Two champagne glasses that have been filled with ingredients to make a venice sunset cocktail. These were made with a cherry sauce, sparkling white grape juice, and grapefruit juice. Cherries were placed on skewers for garnish."}, {"url": "https://food.fnr.sndimg.com/content/dam/images/food/fullset/2010/5/21/0/SM0303_01_venice-sunset-cocktail_s4x3.jpg.rend.hgtvcom.1280.720.suffix/1371593014431.webp", "@type": "ImageObject", "width": "1280", "height": "720", "description": "Two champagne glasses that have been filled with ingredients to make a venice sunset cocktail. These were made with a cherry sauce, sparkling white grape juice, and grapefruit juice. Cherries were placed on skewers for garnish."}], "video": {"name": "Venice Sunset", "@type": "VideoObject", "duration": "PT0H1M28S", "contentUrl": "https://www.foodnetwork.com/apps/api/playback?path=/etc/sni-asset/food/videos/0/01/013/0138/0138641", "uploadDate": "2026-02-13T12:24:43.097-05:00", "description": "The Venice Sunset mocktail can also get a splash of amaretto for grownups..", "thumbnailUrl": "https://food.fnr.sndimg.com/content/dam/images/food/video/8/87/875/8751/875195.jpg.rend.hgtvcom.406.305.suffix/1771003481038.webp"}, "author": [{"url": "https://www.foodnetwork.com/profiles/talent/sandra-lee", "name": "Sandra Lee", "@type": "Person"}], "@context": "http://schema.org", "headline": "Venice Sunset Cocktail", "keywords": "Cherry,Grapefruit Recipes,Grape Recipes", "prepTime": "P0Y0M0DT0H5M0.000S", "publisher": {"url": "https://www.foodnetwork.com", "logo": {"url": "https://food.fnr.sndimg.com/etc/clientlibs/assets/images/food/fn-logo-flat-60x60.png", "@type": "ImageObject", "width": "60", "height": "60"}, "name": "Food Network", "@type": "Organization"}, "totalTime": "P0Y0M0DT0H5M0.000S", "recipeYield": "4 servings", "dateModified": "2014-01-28T15:21:36.815-05:00", "datePublished": "2015-05-30T12:14:12.479-04:00", "recipeCategory": "beverage", "mainEntityOfPage": true, "recipeIngredient": ["12 frozen cherries", "4 (6-inch) bamboo skewers", "1/2 cup grapefruit juice", "1/4 cup sparkling white grape juice", "2 tablespoons reserved cherry sauce from Italian Donuts with Cherry Sauce, cooled", "4 ounces Amaretto liqueur"], "recipeInstructions": [{"text": "Thread 3 frozen cherries onto each skewer. Put in the freezer until ready to garnish the drinks.", "@type": "HowToStep"}, {"text": "Pour 2 tablespoons of grapefruit juice into each of 4 champagne flutes and top with the 1/4 cup of sparkling grape juice. Add 1/2 tablespoon of the reserved cherry sauce and garnish with the frozen cherry skewers.", "@type": "HowToStep"}, {"text": "For the adults, add 1-ounce of Amaretto liqueur.", "@type": "HowToStep"}]}'::jsonb, '2026-04-23 21:04:41.384875+00:00'::timestamptz, '2026-04-25 19:27:06.025346+00:00'::timestamptz, NULL, 'pending_llm', 'v1', '2026-05-03 23:17:54.537080+00:00'::timestamptz, NULL, NULL, NULL);
